window.DB[5]=[{"id":"c05p1","page":58,"title":"POINT 1","sub":"가정법 과거 vs. 가정법 과거완료","prompt":"동사 짝이 되는 단서를 누르세요","pnote":{"t":"if절과 주절의 짝 맞추기","lines":["현재 사실의 반대: if + 과거시제, would + 동사원형","과거 사실의 반대: if + had p.p., would + have p.p."]},"items":[{"no":"예제","chunks":[{"en":"If every computer program suddenly stopped working,","ko":"모든 컴퓨터 프로그램이 갑자기 작동하는 것을 멈춘다면,","k":"C","lab":"C if절 stopped (과거시제)"},{"en":"it would be","ko":"그것은 될 것이다","k":"V","lab":"V be (have been 아님)","h":[["would","c"],["be","v"]]},{"en":"the end of the world.","ko":"세상의 종말이.","k":"","lab":""}],"tr":"모든 컴퓨터 프로그램이 갑자기 작동하는 것을 멈춘다면, 그것은 세상의 종말이 될 것이다.","why":"if절의 동사가 과거시제 <b>stopped</b>(stop: 멈추다)예요. 가정법 과거(지금 사실의 반대)라서 주절은 <b>would + 동사원형</b>이에요. 그래서 <b>be</b>(be: ~이다, ~되다)가 맞아요. have been은 if절이 had p.p.일 때의 짝이에요.","ex":"<b>suddenly</b>는 &ldquo;갑자기&rdquo;예요. stopped는 모양은 과거지만 &ldquo;과거에 멈췄다&rdquo;는 뜻이 아니에요. 지금 사실과 반대로 상상하는 <b>가정법 과거</b>의 과거시제예요.","st":[["c","if절 동사","stopped (과거시제)"],["c","주절 짝","would + 동사원형"],["v","동사","be"]],"verb":{"ok":"be","no":"have been"},"note":{"t":"if절 과거시제 → would + 동사원형","lines":["stopped + would → be","현재 사실의 반대는 if + 과거시제 → would + 동사원형"]},"sx":[["【{c|If} every computer program suddenly {v|stopped} {p|working},】",""],["it {a|would be}","주절 : would + 동사원형"],["the end of the world.",""]]},{"no":"1","chunks":[{"en":"If Robert","ko":"만약 로버트가","k":"S","lab":"S if절 주어"},{"en":"knew the answer to the question,","ko":"그 문제에 대한 답을 안다면,","k":"V","lab":"V knew (had known 아님)","h":[["knew","v"]]},{"en":"he would raise his hand.","ko":"그는 손을 들 것이다.","k":"C","lab":"C 주절 would + 동사원형"}],"tr":"Robert가 그 문제에 대한 답을 안다면, 손을 들 것이다.","why":"주절의 동사가 <b>would raise</b>(raise: 들다)예요. would + 동사원형이면 가정법 과거라서 if절은 과거시제 <b>knew</b>(know: 알다)가 짝이에요. had known은 주절이 would have p.p.일 때 써요.","ex":"","st":[["c","주절","would raise (would + 동사원형)"],["v","if절 동사","knew (과거시제)"]],"verb":{"ok":"knew","no":"had known"},"note":{"t":"주절 would raise로 if절 짝 찾기","lines":["would raise → knew","주절이 would + 동사원형 → if절은 과거시제 knew(알다)"]},"sx":[["【{c|If} Robert",""],["{a|knew} the answer to the question,】","if절 : 가정법 과거"],["he {v|would raise} his hand.",""]]},{"no":"2","chunks":[{"en":"We could have gotten","ko":"우리는 얻을 수 있었을 것이다","k":"C","lab":"C 주절 could have p.p."},{"en":"better seats at the concert yesterday","ko":"어제 콘서트에서 더 좋은 자리를","k":"","lab":""},{"en":"if we","ko":"만약 우리가","k":"S","lab":"S if절 주어"},{"en":"had booked our tickets earlier.","ko":"표를 더 일찍 예매했더라면.","k":"V","lab":"V had booked (booked 아님)","h":[["had booked","v"]]}],"tr":"우리가 더 일찍 표를 예매했더라면 어제 콘서트에서 더 좋은 자리를 얻을 수 있었을 것이다.","why":"주절의 동사가 <b>could have gotten</b>(get: 얻다)이에요. could + have p.p.는 과거 사실의 반대(가정법 과거완료)라서 if절은 <b>had booked</b>(book: 예매하다)가 짝이에요. yesterday(어제)도 과거 단서예요.","ex":"if절이 주절 뒤에 와서 앞에 콤마(,)가 없어요.","st":[["c","주절","could have gotten (could + have p.p.)"],["v","if절 동사","had booked (had p.p.)"]],"verb":{"ok":"had booked","no":"booked"},"note":{"t":"주절 could have p.p.는 과거 반대","lines":["could have gotten → had booked","과거 사실의 반대: if + had p.p. (예매했더라면)"]},"sx":[["We {v|could have gotten}","주절 : could have p.p."],["better seats at the concert yesterday",""],["【{c|if} we",""],["{a|had booked} our tickets earlier.】","if절 : 가정법 과거완료"]]},{"no":"3","chunks":[{"en":"If a vampire","ko":"만약 흡혈귀가","k":"S","lab":"S if절 주어"},{"en":"changed one person a month,","ko":"한 달에 한 명을 바꾼다면,","k":"C","lab":"C if절 changed (과거시제)"},{"en":"there would be","ko":"있을 것이다","k":"V","lab":"V be (have been 아님)","h":[["would","c"],["be","v"]]},{"en":"four vampires two months later.","ko":"두 달 뒤에는 네 명의 흡혈귀가.","k":"","lab":""}],"tr":"만약 흡혈귀가 한 달에 한 명을 바꾼다면, 두 달 뒤에는 네 명의 흡혈귀가 있을 것이다.","why":"if절의 동사가 과거시제 <b>changed</b>(change: 바꾸다)예요. 가정법 과거라서 주절은 would + 동사원형이니까 <b>be</b>가 맞아요.","ex":"<b>two months later</b>(두 달 뒤에)가 있어도, 이 문장은 사실과 반대로 상상하는 이야기라서 가정법 과거를 써요.","st":[["c","if절 동사","changed (과거시제)"],["c","주절 짝","would + 동사원형"],["v","동사","be"]],"verb":{"ok":"be","no":"have been"},"note":{"t":"if절 과거시제 → would + 동사원형","lines":["changed + would → be","과거시제 if절 → would be (현재 사실의 반대)"]},"sx":[["【{c|If} a vampire",""],["{v|changed} one person a month,】","if절 : 가정법 과거"],["there {a|would be}","주절 : would + 동사원형"],["four vampires two months later.",""]]},{"no":"4","chunks":[{"en":"Would you have quit your job then","ko":"당신은 그때 일을 그만두었을 건가요","k":"V","lab":"V have quit (quit 아님)","h":[["Would","c"],["have quit","v"]]},{"en":"if your boss","ko":"만약 상사가","k":"S","lab":"S if절 주어"},{"en":"had moved you to another office?","ko":"당신을 다른 사무실로 옮겼다면?","k":"C","lab":"C if절 had moved (had p.p.)"}],"tr":"상사가 당신을 다른 사무실로 옮겼다면 그때 당신은 일을 그만두었을 건가요?","why":"if절의 동사가 <b>had moved</b>(move: 옮기다)예요. had p.p.는 가정법 과거완료라서 주절은 would + <b>have p.p.</b>인 <b>have quit</b>(quit: 그만두다)이 짝이에요. then(그때)도 과거를 가리켜요.","ex":"<b>Would you ~?</b>처럼 주절이 의문문이어도 짝을 맞추는 방법은 같아요.","st":[["c","if절 동사","had moved (had p.p.)"],["c","주절 짝","Would + have p.p."],["v","동사","have quit"]],"verb":{"ok":"have quit","no":"quit"},"note":{"t":"if절 had p.p. → would have p.p.","lines":["had moved + Would → have quit","if절이 과거완료(옮겼다면) → 주절은 would + have p.p."]},"sx":[["{v|Would} you {a|have quit} your job then","의문문 : Would + 주어 + have p.p."],["【{c|if} your boss",""],["{v|had moved} you to another office?】","if절 : 가정법 과거완료"]]},{"no":"5","chunks":[{"en":"If I","ko":"만약 내가","k":"S","lab":"S if절 주어"},{"en":"had invested in the company,","ko":"그 회사에 투자했더라면,","k":"C","lab":"C if절 had invested (had p.p.)"},{"en":"I would have made","ko":"나는 벌었을 것이다","k":"V","lab":"V have made (made 아님)","h":[["would","c"],["have made","v"]]},{"en":"a lot of money last year.","ko":"많은 돈을 작년에.","k":"","lab":""}],"tr":"내가 그 회사에 투자했더라면, 작년에 돈을 많이 벌었을 것이다.","why":"if절의 동사가 <b>had invested</b>(invest: 투자하다)라서 가정법 과거완료예요. 주절은 would + <b>have p.p.</b>가 짝이라서 <b>made → have made</b>(make: 벌다, 만들다)로 고쳐요. would 뒤에 p.p.(made)만 오면 틀려요.","ex":"<b>make money</b> = 돈을 벌다. last year(작년)도 과거 단서예요.","st":[["c","if절 동사","had invested (had p.p.)"],["c","주절 짝","would + have p.p."],["v","동사","made → have made"]],"verb":{"ok":"have made","no":"made"},"note":{"t":"if절 had p.p. → would have p.p.","lines":["had invested + would → have made","과거 사실의 반대 → would + have p.p.(벌었을 것이다)"]},"sx":[["【{c|If} I",""],["{v|had invested} in the company,】","if절 : 가정법 과거완료"],["I {v|would} {a|have made}","주절 : would have p.p."],["a lot of money last year.",""]]},{"no":"6","chunks":[{"en":"The results could be different","ko":"그 결과는 다를 수 있을 것이다","k":"C","lab":"C 주절 could + 동사원형"},{"en":"if the researchers","ko":"만약 연구원들이","k":"S","lab":"S if절 주어"},{"en":"did the experiment under new conditions.","ko":"새로운 조건에서 실험을 한다면.","k":"V","lab":"V did (이미 맞음)","h":[["did","v"]]}],"tr":"연구원들이 새로운 조건에서 실험을 한다면 그 결과는 다를 수 있을 것이다.","why":"주절의 동사가 <b>could be</b>(could + 동사원형)라서 가정법 과거예요. if절은 과거시제 <b>did</b>(do: 하다)가 짝이에요. 고칠 곳이 없어요.","ex":"did는 &ldquo;과거에 했다&rdquo;가 아니라 가정법 과거(지금 사실의 반대)를 만드는 과거시제예요. experiment는 &ldquo;실험&rdquo;이에요.","st":[["c","주절","could be (could + 동사원형)"],["s","if절 주어","the researchers"],["v","if절 동사","did (맞음)"]],"verb":{"ok":"did","no":"had done"},"note":{"t":"could be → if절 과거시제","lines":["could be + did (맞음)","주절 could + 동사원형 → if절 과거시제 did. 고칠 곳 없음(○)"]},"sx":[["The results {v|could be} different",""],["【{c|if} the researchers",""],["{a|did} the experiment under new conditions.】","if절 : 가정법 과거"]]},{"no":"7","chunks":[{"en":"If I","ko":"만약 내가","k":"S","lab":"S if절 주어"},{"en":"owned this airline,","ko":"이 항공사를 소유하고 있다면,","k":"C","lab":"C if절 owned (과거시제)"},{"en":"I would put","ko":"나는 둘 것이다","k":"V","lab":"V put (have put 아님)","h":[["would","c"],["put","v"]]},{"en":"more space between the seats.","ko":"좌석 사이에 더 많은 공간을.","k":"","lab":""}],"tr":"내가 이 항공사를 소유하고 있다면, 좌석 사이에 더 많은 공간을 둘 것이다.","why":"if절의 동사가 과거시제 <b>owned</b>(own: 소유하다)라서 가정법 과거예요. 주절은 would + <b>동사원형</b>이 짝이라서 <b>have put → put</b>(put: 두다)으로 고쳐요.","ex":"","st":[["c","if절 동사","owned (과거시제)"],["c","주절 짝","would + 동사원형"],["v","동사","have put → put"]],"verb":{"ok":"put","no":"have put"},"note":{"t":"if절 과거시제 → would + 동사원형","lines":["owned + would → put","owned(소유하고 있다면)는 현재 반대 → would put. have put → put"]},"sx":[["【{c|If} I",""],["{v|owned} this airline,】","if절 : 가정법 과거"],["I {v|would} {a|put}","주절 : would + 동사원형"],["more space between the seats.",""]]},{"no":"8","chunks":[{"en":"If you","ko":"만약 당신이","k":"S","lab":"S if절 주어"},{"en":"had turned on a light bulb","ko":"전구를 켰더라면","k":"V","lab":"V had turned (turned 아님)","h":[["had turned","v"]]},{"en":"in the early 1800s,","ko":"1800년대 초에,","k":"C","lab":"C 과거 시간표현"},{"en":"it would have cost you","ko":"그것은 당신에게 비용이 들었을 것이다","k":"C","lab":"C 주절 would have p.p."},{"en":"much more than it does today.","ko":"오늘날 드는 것보다 훨씬 더 많이.","k":"","lab":""}],"tr":"당신이 1800년대 초에 전구를 켰다면, 그것은 당신에게 오늘날 드는 것보다 훨씬 더 많은 비용이 들었을 것이다.","why":"주절의 동사가 <b>would have cost</b>(cost: 비용이 들다)예요. would + have p.p.는 가정법 과거완료라서 if절은 <b>had p.p.</b>가 짝이에요. <b>turned → had turned</b>(turn on: 켜다)로 고쳐요. in the early 1800s(1800년대 초)는 과거 단서예요.","ex":"뒤의 <b>than it does today</b>는 CH04 POINT 3이에요. does는 일반동사 cost를 대신하는 do동사예요.","st":[["c","주절","would have cost (would + have p.p.)"],["m","과거 단서","in the early 1800s"],["v","if절 동사","turned → had turned"]],"verb":{"ok":"had turned","no":"turned"},"note":{"t":"과거 단서·would have p.p. → had p.p.","lines":["in the early 1800s + would have cost → had turned","1800년대 초(과거) 일의 반대 → if + had p.p. → had turned"]},"sx":[["【{c|If} you",""],["{a|had turned on} a light bulb",""],["in the early 1800s,】","if절 : 가정법 과거완료"],["it {v|would have cost} you","주절 : would have p.p."],["much more 【{c|than} it {v|does} today.】","대동사 does : cost 대신 쓴 말"]]}],"taps":[{"k":"C","t":"짝이 되는 단서(if절·주절)를 누르세요"}],"cprompt":"맞는 동사를 고르세요"},{"id":"c05p2","page":59,"title":"POINT 2","sub":"가정법 vs. 조건 부사절","prompt":"가능성을 알려 주는 단서를 누르세요","pnote":{"t":"가능성이 있으면 if + 현재시제","lines":["일어날 수 있는 일: if + 현재시제, will(can) + 동사원형","사실과 반대·가능성 없는 일: if + 과거시제 / had p.p."]},"items":[{"no":"예제","chunks":[{"en":"If you","ko":"만약 당신이","k":"S","lab":"S if절 주어"},{"en":"rub your hands together quickly,","ko":"손을 모아 빠르게 비비면,","k":"V","lab":"V rub (rubbed 아님)","h":[["rub","v"]]},{"en":"they will get warmer.","ko":"그것들은 더 따뜻해질 것이다.","k":"C","lab":"C 주절 will (가능성 있음)"}],"tr":"만약 당신이 손을 모아 빠르게 비비면, 더 따뜻해질 것이다.","why":"주절의 동사가 <b>will get</b>이에요. 손을 비비면 따뜻해지는 것은 실제로 일어날 수 있는 일(가능성 있는 일)이라서 조건 부사절이에요. 그래서 if절에는 현재시제 <b>rub</b>(rub: 비비다)을 써요. rubbed는 사실과 반대인 일에 쓰는 가정법 과거예요.","ex":"<b>get warmer</b> = 더 따뜻해지다. 조건 부사절의 if절에는 미래의 일이라도 will을 쓰지 않아요.","st":[["c","가능성","일어날 수 있는 일"],["c","주절","will get"],["v","if절 동사","rub (현재시제)"]],"verb":{"ok":"rub","no":"rubbed"},"note":{"t":"가능성 있는 일 → if + 현재시제","lines":["will get → rub","손을 비비면 따뜻해지는 일은 실제로 가능 → 현재시제 rub"]},"sx":[["【{c|If} you",""],["{a|rub} your hands together quickly,】","조건절 : 현재형으로 미래 의미"],["they {v|will get} warmer.","주절 : will + 동사원형"]]},{"no":"1","chunks":[{"en":"If you","ko":"만약 당신이","k":"S","lab":"S if절 주어"},{"en":"lived on the moon,","ko":"달에 산다면,","k":"V","lab":"V lived (이미 맞음)","h":[["lived","v"]]},{"en":"you would be lighter than here on Earth.","ko":"당신은 여기 지구에서보다 더 가벼울 것이다.","k":"C","lab":"C 주절 would (가능성 없음)"}],"tr":"당신이 달에 산다면, 당신은 여기 지구에서보다 더 가벼울 것이다.","why":"주절의 동사가 <b>would be</b>예요. 달에 사는 것은 지금 사실과 반대인 일(가능성 없는 일)이라서 가정법 과거예요. if절에 과거시제 <b>lived</b>(live: 살다)는 맞아요. 고칠 곳이 없어요.","ex":"<b>lighter than here on Earth</b>는 &ldquo;여기 지구에서보다 더 가벼운&rdquo;이라는 뜻이에요.","st":[["c","가능성","달에 사는 것 (가능성 없음)"],["c","주절","would be"],["v","if절 동사","lived (맞음)"]],"verb":{"ok":"lived","no":"live"},"note":{"t":"가능성 없는 일 → if + 과거시제","lines":["would be + lived (맞음)","달에 사는 것은 현실이 아님 → 가정법 과거 lived. 고칠 곳 없음(○)"]},"sx":[["【{c|If} you",""],["{a|lived} on the moon,】","if절 : 가정법 과거"],["you {v|would be} lighter than here on Earth.",""]]},{"no":"2","chunks":[{"en":"The child will become a great dancer","ko":"그 아이는 훌륭한 무용수가 될 것이다","k":"C","lab":"C 주절 will (가능성 있음)"},{"en":"if he","ko":"만약 그가","k":"S","lab":"S if절 주어"},{"en":"receives professional training.","ko":"전문적인 훈련을 받으면.","k":"V","lab":"V receives (received 아님)","h":[["receives","v"]]}],"tr":"만약 전문적인 훈련을 받으면 그 아이는 훌륭한 무용수가 될 것이다.","why":"주절의 동사가 <b>will become</b>이에요. 훈련을 받으면 무용수가 될 수 있다는 것은 일어날 가능성이 있는 일이라서 조건 부사절이에요. if절에는 현재시제를 써서 <b>received → receives</b>(receive: 받다)로 고쳐요. 주어 he가 단수라서 -s가 붙어요.","ex":"","st":[["c","주절","will become"],["c","가능성","일어날 수 있는 일"],["v","if절 동사","received → receives"]],"verb":{"ok":"receives","no":"received"},"note":{"t":"가능성 있는 일 → if + 현재시제","lines":["will become → receives","주절 will → 일어날 수 있는 일 → 현재시제 receives(받다)"]},"sx":[["The child {v|will become} a great dancer",""],["【{c|if} he",""],["{a|receives} professional training.】","조건절 : 현재형으로 미래 의미"]]},{"no":"3","chunks":[{"en":"If the Wright brothers","ko":"만약 라이트 형제가","k":"S","lab":"S if절 주어"},{"en":"had invented airplanes sooner,","ko":"비행기를 더 빨리 발명했다면,","k":"V","lab":"V had invented (이미 맞음)","h":[["had invented","v"]]},{"en":"air travel would have started","ko":"항공 여행은 시작되었을 것이다","k":"C","lab":"C 주절 would have p.p."},{"en":"much earlier.","ko":"훨씬 더 일찍.","k":"","lab":""}],"tr":"라이트 형제가 비행기를 더 빨리 발명했다면, 항공 여행은 훨씬 더 일찍 시작되었을 것이다.","why":"주절의 동사가 <b>would have started</b>(start: 시작하다)이에요. 과거 사실과 반대인 일이라서 가정법 과거완료예요. if절의 <b>had invented</b>(invent: 발명하다)는 짝이 맞아요. 고칠 곳이 없어요.","ex":"","st":[["c","가능성","과거 사실의 반대"],["c","주절","would have started"],["v","if절 동사","had invented (맞음)"]],"verb":{"ok":"had invented","no":"invented"},"note":{"t":"과거 사실의 반대 → had p.p.","lines":["would have started + had invented (맞음)","주절 would have p.p. → if절 had p.p. 고칠 곳 없음(○)"]},"sx":[["【{c|If} the Wright brothers",""],["{a|had invented} airplanes sooner,】","if절 : 가정법 과거완료"],["air travel {v|would have started}",""],["much earlier.",""]]},{"no":"4","chunks":[{"en":"If you","ko":"만약 당신이","k":"S","lab":"S if절 주어"},{"en":"are afraid of standing on balconies,","ko":"발코니에 서는 것을 두려워한다면,","k":"V","lab":"V are (were 아님)","h":[["are","v"]]},{"en":"you can try starting on a lower floor.","ko":"당신은 더 낮은 층에서 시작하는 것을 시도해 볼 수 있다.","k":"C","lab":"C 주절 can (가능성 있음)"}],"tr":"만약 당신이 발코니에 서는 것을 두려워한다면, 더 낮은 층에서 시작하는 것을 시도해 볼 수 있다.","why":"주절의 동사가 <b>can try</b>예요. 가정법이라면 could가 와야 해요. 이 문장은 정말 무서운 사람에게 하는 실제 조언이라서 가능성 있는 일(조건 부사절)이에요. if절에 현재시제로 <b>were → are</b>(be: ~이다)로 고쳐요.","ex":"<b>try + v-ing</b> = (시험 삼아) ~해 보다. <b>be afraid of ~</b> = ~을 두려워하다.","st":[["c","주절","can try (could가 아님)"],["c","가능성","실제 조언 (가능성 있음)"],["v","if절 동사","were → are"]],"verb":{"ok":"are","no":"were"},"note":{"t":"실제 조언이면 if + 현재시제","lines":["can try → are","can try는 실제로 해볼 수 있는 조언 → 현재시제 are(~이다)"]},"sx":[["【{c|If} you",""],["{a|are} afraid of {p|standing} on balconies,】","be afraid of + 동명사 : ~을 두려워하다"],["you {v|can try} {p|starting} on a lower floor.","try + 동명사 : 시험 삼아 ~해 보다"]]},{"no":"5","chunks":[{"en":"Many people would help","ko":"많은 사람들이 도와줄 것이다","k":"C","lab":"C 주절 would (사실과 반대)"},{"en":"if I","ko":"만약 내가","k":"S","lab":"S if절 주어"},{"en":"asked them,","ko":"그들에게 요청한다면,","k":"V","lab":"V asked (ask 아님)","h":[["asked","v"]]},{"en":"but I prefer to solve problems myself.","ko":"하지만 나는 스스로 문제를 해결하는 것을 선호한다.","k":"","lab":""}],"tr":"내가 요청하면 많은 사람들이 도와줄 것이지만, 나는 스스로 문제를 해결하는 것을 선호한다.","why":"주절의 동사가 <b>would help</b>(would + 동사원형)예요. 뒤의 but I prefer to solve problems myself(스스로 해결하는 것을 선호한다)를 보면 &ldquo;요청하지 않는다&rdquo;는 현재 사실의 반대예요. 그래서 가정법 과거로, if절에 과거시제 <b>ask → asked</b>(ask: 요청하다)로 고쳐요.","ex":"<b>prefer to V</b> = V하는 것을 더 좋아하다. <b>myself</b>는 &ldquo;나 스스로&rdquo;예요.","st":[["c","주절","would help (would + 동사원형)"],["c","가능성","요청하지 않음 (사실과 반대)"],["v","if절 동사","ask → asked"]],"verb":{"ok":"asked","no":"ask"},"note":{"t":"요청하지 않음 → 가정법 과거","lines":["would help → asked","but 뒤에서 요청하지 않는다고 함 → 사실과 반대 → 과거시제 asked(요청하다)"]},"sx":[["Many people {v|would help}",""],["【{c|if} I",""],["{a|asked} them,】","if절 : 가정법 과거"],["{c|but} I {v|prefer} {p|to} solve problems myself.","but : 앞뒤 절을 대조로 연결"]]}],"taps":[{"k":"C","t":"가능성 단서(주절·상황)를 누르세요"}],"cprompt":"맞는 동사를 고르세요"},{"id":"c05p3","page":59,"title":"POINT 3","sub":"as if 가정법","prompt":"주절 동사의 시제를 누르세요","pnote":{"t":"as if 뒤 시제는 주절 동사와 비교","lines":["주절과 같은 때: as if + 과거시제 (were 등)","주절보다 앞선 때: as if + had p.p."]},"items":[{"no":"예제","chunks":[{"en":"Thanks to the medicine, you feel","ko":"약 덕분에, 너는 느낀다","k":"C","lab":"C 주절 feel (현재)"},{"en":"as if you","ko":"마치 네가","k":"S","lab":"S as if절 주어"},{"en":"were fine","ko":"괜찮은 것처럼","k":"V","lab":"V were (had been 아님)","h":[["were","v"]]},{"en":"now,","ko":"지금,","k":"M","lab":"M 같은 때 (지금)"},{"en":"but the feeling is only temporary.","ko":"하지만 그 느낌은 일시적일 뿐이다.","k":"","lab":""}],"tr":"약 덕분에, 너는 지금 괜찮은 것처럼 느끼지만, 그 느낌은 일시적일 뿐이다.","why":"주절의 동사가 <b>feel</b>(feel: 느끼다, 현재)이고, 괜찮은 것도 <b>now</b>(지금)예요. 느끼는 때와 괜찮은 때가 같은 시점이라서 as if절에 과거시제 <b>were</b>(be: ~이다)가 맞아요. had been은 &ldquo;더 이전&rdquo;일 때 써요.","ex":"<b>Thanks to ~</b> = ~ 덕분에. temporary는 &ldquo;일시적인&rdquo;이에요. 가정법에서는 주어가 you나 he여도 be동사로 were를 써요.","st":[["v","주절 동사","feel (현재)"],["m","시점","now (같은 때)"],["v","as if절","were (과거시제)"]],"verb":{"ok":"were","no":"had been"},"note":{"t":"주절과 같은 때 → as if + 과거시제","lines":["feel + now → were","feel(현재)과 now(지금)가 같은 때 → were"]},"sx":[["Thanks to the medicine, you {v|feel}",""],["【{c|as if} you",""],["{a|were} fine】","as if + 가정법 : 마치 ~인 것처럼"],["now,",""],["{c|but} the feeling {v|is} only temporary.",""]]},{"no":"1","chunks":[{"en":"The athlete plays every match","ko":"그 운동선수는 모든 경기를 한다","k":"C","lab":"C 주절 plays (현재)"},{"en":"as if it","ko":"마치 그것이","k":"S","lab":"S as if절 주어"},{"en":"were a final match.","ko":"결승전인 것처럼.","k":"V","lab":"V were (had been 아님)","h":[["were","v"]]}],"tr":"그 운동선수는 모든 경기를 마치 그것이 결승전인 것처럼 한다.","why":"주절의 동사 <b>plays</b>(play: 경기하다, 현재)와 결승전인 것처럼 하는 때가 같아요. 같은 시점이라서 as if절에 과거시제 <b>were</b>(be: ~이다)가 맞아요.","ex":"<b>final match</b>는 &ldquo;결승전&rdquo;이에요.","st":[["v","주절 동사","plays (현재)"],["v","as if절","were (같은 시점)"]],"verb":{"ok":"were","no":"had been"},"note":{"t":"주절과 같은 때 → as if + 과거시제","lines":["plays → were","plays(현재)와 같은 때의 상상 → were"]},"sx":[["The athlete {v|plays} every match",""],["【{c|as if} it",""],["{a|were} a final match.】","as if + 가정법 과거 : 마치 ~인 것처럼"]]},{"no":"2","chunks":[{"en":"Angela spoke","ko":"앤젤라는 말했다","k":"C","lab":"C 주절 spoke (과거)"},{"en":"as if she","ko":"마치 그녀가","k":"S","lab":"S as if절 주어"},{"en":"had seen the car accident","ko":"그 자동차 사고를 봤던 것처럼","k":"V","lab":"V had seen (saw 아님)","h":[["had seen","v"]]},{"en":"the day before,","ko":"전날에,","k":"M","lab":"M 더 앞선 시점"},{"en":"but she wasn’t there.","ko":"하지만 그녀는 거기에 있지 않았다.","k":"","lab":""}],"tr":"Angela는 마치 전날 자동차 사고를 본 것처럼 말했지만, 그녀는 거기에 있지 않았다.","why":"주절의 동사 <b>spoke</b>(speak: 말하다의 과거형)는 과거예요. 사고를 본 것은 <b>the day before</b>(전날)이니까 말한 때보다 더 앞선 일이에요. 그래서 as if절에 <b>had seen</b>(see: 보다)이 맞아요.","ex":"","st":[["v","주절 동사","spoke (과거)"],["m","더 앞선 시점","the day before"],["v","as if절","had seen"]],"verb":{"ok":"had seen","no":"saw"},"note":{"t":"주절보다 앞선 때 → as if + had p.p.","lines":["spoke + the day before → had seen","spoke(말했다)보다 전날의 일 → had seen"]},"sx":[["Angela {v|spoke}",""],["【{c|as if} she",""],["{a|had seen} the car accident","as if + had p.p. : 마치 ~했던 것처럼"],["the day before,】",""],["{c|but} she {v|wasn’t} there.",""]]},{"no":"3","chunks":[{"en":"He","ko":"그는","k":"S","lab":"S 주절 주어"},{"en":"acted","ko":"행동했다","k":"C","lab":"C 주절 acted (과거)"},{"en":"as if he had visited the city many times,","ko":"마치 그가 그 도시를 여러 번 방문했던 것처럼,","k":"V","lab":"V had visited (visited 아님)","h":[["he","s"],["had visited","v"]]},{"en":"but this was actually his first time.","ko":"하지만 사실 이번이 처음이었다.","k":"","lab":""}],"tr":"그는 마치 그 도시를 여러 번 방문했던 것처럼 행동했지만, 사실 이번이 처음이었다.","why":"행동한 것(acted: act 행동하다의 과거형)보다 도시를 방문했던 것이 먼저 일어난 일이에요. 앞선 시점이라서 <b>had visited</b>(visit: 방문하다)가 맞아요.","ex":"뒤의 <b>this was actually his first time</b>(사실 이번이 처음이었다)이 &ldquo;방문했던 것처럼&rdquo;이 사실과 반대라는 걸 알려 줘요.","st":[["v","주절 동사","acted (과거)"],["c","더 앞선 일","여러 번 방문했던 것"],["v","as if절","had visited"]],"verb":{"ok":"had visited","no":"visited"},"note":{"t":"주절보다 앞선 때 → as if + had p.p.","lines":["acted + many times → had visited","행동한 때보다 앞선 경험(여러 번 방문했던) → had visited"]},"sx":[["He",""],["{v|acted}",""],["【{c|as if} he {a|had visited} the city many times,】","as if + had p.p. : 마치 ~했던 것처럼"],["{c|but} this {v|was} actually his first time.",""]]},{"no":"4","chunks":[{"en":"My dog sometimes barks at the air","ko":"나의 개는 때때로 허공에 대고 짖는다","k":"C","lab":"C 주절 barks (현재)"},{"en":"as if someone","ko":"마치 누군가","k":"S","lab":"S as if절 주어"},{"en":"were there.","ko":"거기에 있는 것처럼.","k":"V","lab":"V were (had been 아님)","h":[["were","v"]]}],"tr":"나의 개는 때때로 마치 누군가 거기에 있는 것처럼 허공에 대고 짖는다.","why":"주절의 동사 <b>barks</b>(bark: 짖다, 현재)와 누군가 거기에 있는 때가 같아요. 같은 시점이라서 <b>were</b>(be: ~이다)가 맞아요. someone은 단수지만 가정법에서는 were를 써요.","ex":"","st":[["v","주절 동사","barks (현재)"],["v","as if절","were (같은 시점)"]],"verb":{"ok":"were","no":"had been"},"note":{"t":"주절과 같은 때 → as if + 과거시제","lines":["barks → were","barks(현재)와 같은 때의 상상 → were"]},"sx":[["My dog sometimes {v|barks} at the air",""],["【{c|as if} someone",""],["{a|were} there.】","as if + 가정법 과거 : 마치 ~인 것처럼"]]},{"no":"5","chunks":[{"en":"Jackson knows very little,","ko":"잭슨은 아는 것이 거의 없지만,","k":"C","lab":"C 앞 동사 knows (현재)"},{"en":"but he often behaves","ko":"그는 종종 행동한다","k":"C","lab":"C 주절 behaves (현재)"},{"en":"as if he","ko":"마치 그가","k":"S","lab":"S as if절 주어"},{"en":"had all the answers.","ko":"모든 답을 가지고 있는 것처럼.","k":"V","lab":"V had (had had 아님)","h":[["had","v"]]}],"tr":"Jackson은 아는 것이 거의 없지만, 종종 마치 모든 답을 가지고 있는 것처럼 행동한다.","why":"주절의 동사 <b>behaves</b>(behave: 행동하다, 현재)와 모든 답을 가지고 있는 때가 같아요. 같은 시점이라서 과거시제 <b>had</b>(have: 가지다)가 맞아요. had had는 &ldquo;더 이전에 가졌던&rdquo; 일일 때 써요.","ex":"<b>knows very little</b>(거의 아는 게 없다)이라서 &ldquo;모든 답을 가진 것처럼&rdquo;은 사실과 반대예요. 이것이 as if 가정법의 핵심이에요.","st":[["v","주절 동사","behaves (현재)"],["v","as if절","had (같은 시점)"]],"verb":{"ok":"had","no":"had had"},"note":{"t":"주절과 같은 때 → as if + 과거시제","lines":["behaves → had","behaves(현재)와 같은 때 → had(가지고 있다의 과거형)"]},"sx":[["Jackson {v|knows} very little,",""],["{c|but} he often {v|behaves}",""],["【{c|as if} he",""],["{a|had} all the answers.】","as if + 가정법 과거 : 마치 ~인 것처럼"]]}],"taps":[{"k":"C","t":"주절 동사(시제 기준)를 누르세요"}],"cprompt":"as if 뒤 맞는 동사를 고르세요"},{"id":"c05q1","page":60,"title":"문장 연습 네모","sub":"둘 중 어법에 맞는 것 고르기","prompt":"시제 단서(if절·주절)를 누르세요","pnote":{"t":"가정법 동사 짝 맞추기","lines":["if절 과거 → would + 동사원형 / if절 had p.p. → would + have p.p. / as if절은 주절과 같은 시점이면 과거, 더 앞선 시점이면 had p.p."]},"items":[{"no":"1","chunks":[{"en":"If there existed a time machine,","ko":"타임머신이 존재한다면,","k":"C","lab":"C if절 동사 existed (과거시제)","h":[["existed","c"]]},{"en":"I would visit","ko":"나는 방문할 것이다","k":"V","lab":"V visit (have visited 아님)","h":[["would","c"],["visit","v"]]},{"en":"the future.","ko":"미래를.","k":"","lab":""}],"tr":"타임머신이 존재한다면, 나는 미래를 방문할 것이다.","why":"if절의 동사가 과거시제 <b>existed</b>(exist: 존재하다)예요. 가정법 과거라서 주절은 would + 동사원형인 <b>visit</b>(visit: 방문하다)이 짝이에요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","existed (과거시제)"],["c","주절","would + 동사원형"],["v","동사","visit"]],"verb":{"ok":"visit","no":"have visited"},"note":{"t":"if절이 과거면 would + 동사원형","lines":["existed → would visit","지금 사실과 반대인 가정 → would 뒤에 동사원형"]},"taps":[{"k":"C","t":"if절 동사를 누르세요"}],"sx":[["【{c|If} there {v|existed} a time machine,】","if절 : 가정법 과거"],["I {v|would} {a|visit}",""],["the future.",""]]},{"no":"2","chunks":[{"en":"Mark","ko":"마크는","k":"S","lab":"S 주어"},{"en":"would have gotten","ko":"받았을 것이다","k":"C","lab":"C 주절 would have gotten"},{"en":"a perfect score","ko":"만점을","k":"","lab":""},{"en":"if he had solved","ko":"그가 풀었다면","k":"V","lab":"V had solved (solved 아님)","h":[["if","c"],["had solved","v"]]},{"en":"the last question.","ko":"마지막 문제를.","k":"","lab":""}],"tr":"마지막 문제를 풀었다면 Mark는 만점을 받았을 것이다.","why":"주절의 동사가 <b>would have gotten</b>(get: 얻다)이에요. would + have p.p.는 가정법 과거완료라서 if절은 <b>had solved</b>(solve: 풀다)가 짝이에요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","주절","would have gotten (would + have p.p.)"],["c","if절 동사","had solved (had p.p.)"]],"verb":{"ok":"had solved","no":"solved"},"note":{"t":"주절이 would have p.p.면 if절은 had p.p.","lines":["would have gotten → had solved","과거 사실과 반대인 가정 → if절 had p.p."]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["Mark",""],["{v|would have gotten}","주절 : would have p.p."],["a perfect score",""],["【{c|if} he {a|had solved}","if절 : 가정법 과거완료"],["the last question.】",""]]},{"no":"3","chunks":[{"en":"If readers","ko":"독자들이","k":"S","lab":"S 주어"},{"en":"look at the story","ko":"이야기를 본다면","k":"V","lab":"V look (looked 아님)","h":[["look","v"]]},{"en":"through another character’s eyes,","ko":"다른 등장인물의 눈을 통해,","k":"","lab":""},{"en":"they will interpret","ko":"그들은 해석할 것이다","k":"C","lab":"C 주절 will interpret","h":[["will interpret","c"]]},{"en":"it differently.","ko":"그것을 다르게.","k":"","lab":""}],"tr":"독자들이 다른 등장인물의 눈을 통해 이야기를 본다면, 그들은 그것을 다르게 해석할 것이다.","why":"주절의 동사가 <b>will interpret</b>(interpret: 해석하다)예요. will은 실제로 일어날 수 있는 일(조건 부사절)에 쓰니까, if절에는 현재시제 <b>look</b>(look: 보다)이 맞아요.","ex":"<b>일어날 수 있는 일</b>(조건 부사절)은 if절에 <b>현재시제</b>를 써요. 주절은 will 등이에요. 미래의 일이어도 if절에는 will을 쓰지 않아요.","st":[["c","주절","will interpret"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","look (현재시제)"]],"verb":{"ok":"look","no":"looked"},"note":{"t":"주절이 will이면 if절은 현재시제","lines":["will interpret → look","일어날 수 있는 일 → if절은 현재시제(미래 will은 쓰지 않음)"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["【{c|If} readers",""],["{a|look} at the story",""],["through another character’s eyes,】","조건절 : 현재형으로 미래 의미"],["they {v|will interpret}",""],["it differently.",""]]},{"no":"4","chunks":[{"en":"The flowers in the painting look","ko":"그림 속의 꽃들은 보인다","k":"C","lab":"C 주절 동사 look (현재)","h":[["look","c"]]},{"en":"as if they","ko":"마치 그것들이","k":"S","lab":"S 주어"},{"en":"were alive.","ko":"살아 있는 것처럼.","k":"V","lab":"V were (had been 아님)","h":[["were","v"]]}],"tr":"그림 속의 꽃들은 마치 살아 있는 것처럼 보인다.","why":"주절의 동사 <b>look</b>(look: 보이다, 현재)과 살아 있는 때가 같아요. 같은 시점이라서 as if절에 과거시제 <b>were</b>(be: ~이다)가 맞아요.","ex":"<b>as if</b>: 주절과 같은 때의 일이면 <b>과거시제</b>(be동사는 were), 주절보다 더 앞선 일이면 <b>had p.p.</b>","st":[["v","주절 동사","look (현재)"],["v","as if절","were (같은 시점)"]],"verb":{"ok":"were","no":"had been"},"note":{"t":"as if절은 주절과 같은 시점이면 과거","lines":["look → as if ~ were","보이는 때와 살아 있는 때가 같다 → were"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["The flowers in the painting {v|look}",""],["【{c|as if} they",""],["{a|were} alive.】","as if + 가정법 과거 : 마치 ~인 것처럼"]]},{"no":"5","chunks":[{"en":"Stephanie","ko":"스테파니는","k":"S","lab":"S 주어"},{"en":"would own a dog","ko":"개를 키울 것이다","k":"C","lab":"C 주절 would own","h":[["would own","c"]]},{"en":"if she had","ko":"그녀가 가지고 있다면","k":"V","lab":"V had (had had 아님)","h":[["if","c"],["had","v"]]},{"en":"a house with a bigger backyard.","ko":"더 큰 뒷마당이 있는 집을.","k":"","lab":""}],"tr":"Stephanie가 더 큰 뒷마당이 있는 집을 가지고 있다면 개를 키울 것이다.","why":"주절의 동사가 <b>would own</b>(would + 동사원형)이라서 가정법 과거예요. if절은 과거시제 <b>had</b>(have: 가지다)가 짝이에요. had had는 would have p.p.와 짝이에요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","주절","would own (would + 동사원형)"],["c","if절 동사","had (과거시제)"]],"verb":{"ok":"had","no":"had had"},"note":{"t":"주절이 would + 동사원형이면 if절은 과거","lines":["would own → had","지금 사실과 반대인 가정 → if절 과거시제"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["Stephanie",""],["{v|would own} a dog",""],["【{c|if} she {a|had}","if절 : 가정법 과거"],["a house with a bigger backyard.】",""]]},{"no":"6","chunks":[{"en":"The soup tasted","ko":"그 수프는 맛이 났다","k":"C","lab":"C 주절 동사 tasted (과거)","h":[["tasted","c"]]},{"en":"as if the chef","ko":"마치 요리사가","k":"S","lab":"S 주어"},{"en":"had forgotten to add some salt and pepper.","ko":"소금과 후추를 더하는 것을 잊은 것처럼.","k":"V","lab":"V had forgotten (forgot 아님)","h":[["had forgotten","v"]]}],"tr":"그 수프는 마치 요리사가 소금과 후추를 더하는 것을 잊은 것처럼 맛이 났다.","why":"주절의 동사 <b>tasted</b>(taste: 맛이 나다의 과거형)보다 요리사가 소금과 후추를 더하는 것을 잊은 일이 먼저예요. 앞선 시점이라서 as if절에 <b>had forgotten</b>(forget: 잊다)이 맞아요.","ex":"<b>as if</b>: 주절과 같은 때의 일이면 <b>과거시제</b>(be동사는 were), 주절보다 더 앞선 일이면 <b>had p.p.</b>","st":[["v","주절 동사","tasted (과거)"],["v","as if절","had forgotten (더 앞선 시점)"]],"verb":{"ok":"had forgotten","no":"forgot"},"note":{"t":"as if절이 더 앞선 시점이면 had p.p.","lines":["tasted → had forgotten","맛이 난 때보다 요리사가 잊은 때가 더 앞선다 → had p.p."]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["The soup {v|tasted}",""],["【{c|as if} the chef",""],["{a|had forgotten} {p|to} add some salt and pepper.】","as if + had p.p. : 마치 ~했던 것처럼"]]},{"no":"7","chunks":[{"en":"If early humans","ko":"초기 인류가","k":"S","lab":"S 주어"},{"en":"had not used language,","ko":"언어를 사용하지 않았다면,","k":"C","lab":"C if절 동사 had not used (had p.p.)","h":[["had not used","c"]]},{"en":"the business deal","ko":"사업 거래는","k":"","lab":""},{"en":"would have been impossible.","ko":"불가능했을 것이다.","k":"V","lab":"V have been (be 아님)","h":[["would","c"],["have been","v"]]}],"tr":"초기 인류가 언어를 사용하지 않았다면, 사업 거래는 불가능했을 것이다.","why":"if절의 동사가 <b>had not used</b>(use: 사용하다)예요. had p.p.는 가정법 과거완료라서 주절은 would + <b>have p.p.</b>인 <b>have been</b>(be: ~이다)이 짝이에요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","had not used (had p.p.)"],["c","주절","would + have p.p."],["v","동사","have been"]],"verb":{"ok":"have been","no":"be"},"note":{"t":"if절이 had p.p.면 주절은 would have p.p.","lines":["had not used → would have been","과거 사실과 반대인 가정 → would + have p.p."]},"taps":[{"k":"C","t":"if절 동사를 누르세요"}],"sx":[["【{c|If} early humans",""],["{v|had not used} language,】","if절 : 가정법 과거완료"],["the business deal",""],["{v|would} {a|have been} impossible.","주절 : would have p.p."]]},{"no":"8","chunks":[{"en":"If a person","ko":"한 사람이","k":"S","lab":"S 주어"},{"en":"takes more risks,","ko":"더 많은 위험을 감수한다면,","k":"V","lab":"V takes (took 아님)","h":[["takes","v"]]},{"en":"he or she will have","ko":"그 또는 그녀는 가질 것이다","k":"C","lab":"C 주절 will have","h":[["will have","c"]]},{"en":"more chances for success.","ko":"성공을 위한 더 많은 기회를.","k":"","lab":""}],"tr":"만약 한 사람이 더 많은 위험을 감수한다면, 그 또는 그녀는 성공을 위한 기회가 더 많을 것이다.","why":"주절의 동사가 <b>will have</b>예요. 위험을 더 감수하면 기회가 늘어난다는 것은 실제로 일어날 수 있는 일(조건 부사절)이라서 if절에 현재시제 <b>takes</b>(take: 감수하다)가 맞아요. 주어 a person이 단수라서 takes예요.","ex":"<b>take risks</b> = 위험을 감수하다.","st":[["c","주절","will have"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","takes (현재시제)"]],"verb":{"ok":"takes","no":"took"},"note":{"t":"주절이 will이면 if절은 현재시제","lines":["will have → takes","일어날 수 있는 일 → if절은 현재시제"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["【{c|If} a person",""],["{a|takes} more risks,】","조건절 : 현재형으로 미래 의미"],["he or she {v|will have}",""],["more chances for success.",""]]},{"no":"9","chunks":[{"en":"The team","ko":"그 팀은","k":"S","lab":"S 주어"},{"en":"could have finished the project","ko":"프로젝트를 끝낼 수 있었을 것이다","k":"V","lab":"V have finished (finish 아님)","h":[["could","c"],["have finished","v"]]},{"en":"last week","ko":"지난주에","k":"M","lab":"M 시간 단서 last week (과거)"},{"en":"if they had had","ko":"그들이 가지고 있었다면","k":"C","lab":"C if절 동사 had had (had p.p.)","h":[["if","c"],["had had","c"]]},{"en":"one more member.","ko":"한 명의 팀원이 더.","k":"","lab":""}],"tr":"그 팀은 한 명의 팀원이 더 있었다면 지난주에 프로젝트를 끝낼 수 있었을 것이다.","why":"if절의 동사가 <b>had had</b>(have: 가지다의 과거완료)예요. had p.p.는 가정법 과거완료라서 주절은 could + <b>have p.p.</b>인 <b>have finished</b>(finish: 끝내다)가 짝이에요. last week(지난주)도 과거 단서예요.","ex":"<b>had had</b> = had(과거완료를 만드는 말) + had(have의 p.p.)예요. 어색해 보여도 정상 표현이에요.","st":[["c","if절 동사","had had (had p.p.)"],["c","주절","could + have p.p."],["v","동사","have finished"]],"verb":{"ok":"have finished","no":"finish"},"note":{"t":"과거 시간 단서 + had p.p.는 could have p.p.","lines":["last week, had had → could have finished","지난주 일 + 과거 사실과 반대 → have p.p."]},"taps":[{"k":"M","t":"시간 단서를 누르세요"},{"k":"C","t":"if절 동사를 누르세요"}],"sx":[["The team",""],["{v|could} {a|have finished} the project",""],["last week",""],["【{c|if} they {v|had had}","had had : have(가지다)의 과거완료"],["one more member.】",""]]},{"no":"10","chunks":[{"en":"Jessie","ko":"제시는","k":"S","lab":"S 주어"},{"en":"always enters her sister’s room without knocking","ko":"항상 노크 없이 언니 방에 들어간다","k":"C","lab":"C 주절 동사 enters (현재)","h":[["enters","c"]]},{"en":"as if it were","ko":"마치 그것이 ~인 것처럼","k":"V","lab":"V were (had been 아님)","h":[["as if","c"],["were","v"]]},{"en":"her own room.","ko":"자기 방.","k":"","lab":""}],"tr":"Jessie는 마치 자기 방인 것처럼 항상 노크 없이 언니 방에 들어간다.","why":"주절의 동사 <b>enters</b>(enter: 들어가다, 현재)와 자기 방인 것처럼 하는 때가 같아요. 같은 시점이라서 <b>were</b>(be: ~이다)가 맞아요. always(항상)가 있어서 현재 습관 이야기예요.","ex":"<b>without knocking</b> = 노크하지 않고. 전치사 without 뒤에는 v-ing가 와요.","st":[["v","주절 동사","enters (현재)"],["v","as if절","were (같은 시점)"]],"verb":{"ok":"were","no":"had been"},"note":{"t":"as if절은 주절과 같은 시점이면 과거","lines":["enters → as if ~ were","들어가는 때와 같은 때의 일 → were"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["Jessie",""],["always {v|enters} her sister’s room without {p|knocking}","전치사 + 동명사 : ~하지 않고"],["【{c|as if} it {a|were}","as if + 가정법 과거 : 마치 ~인 것처럼"],["her own room.】",""]]},{"no":"11","chunks":[{"en":"If I","ko":"내가","k":"S","lab":"S 주어"},{"en":"had the power","ko":"힘이 있다면","k":"C","lab":"C if절 동사 had (과거시제)","h":[["had","c"]]},{"en":"to control the weather,","ko":"날씨를 조절할,","k":"","lab":""},{"en":"I would make","ko":"나는 만들 것이다","k":"V","lab":"V make (have made 아님)","h":[["would","c"],["make","v"]]},{"en":"this rain stop.","ko":"이 비가 멈추게.","k":"","lab":""}],"tr":"내가 날씨를 조절할 수 있는 힘이 있다면, 이 비를 멈추게 할 것이다.","why":"if절의 동사가 과거시제 <b>had</b>(have: 가지다)예요. 가정법 과거라서 주절은 would + 동사원형인 <b>make</b>(make: 만들다)가 짝이에요. 이 had는 &ldquo;가졌었다&rdquo;가 아니라 지금 사실과 반대로 상상하는 말이에요.","ex":"<b>make this rain stop</b> = 이 비를 멈추게 하다(make + 목적어 + 동사원형).","st":[["c","if절 동사","had (과거시제)"],["c","주절","would + 동사원형"],["v","동사","make"]],"verb":{"ok":"make","no":"have made"},"note":{"t":"if절이 과거면 would + 동사원형","lines":["had → would make","지금 사실과 반대인 가정 → would 뒤에 동사원형"]},"taps":[{"k":"C","t":"if절 동사를 누르세요"}],"sx":[["【{c|If} I",""],["{v|had} the power","if절 : 가정법 과거"],["【{p|to} control the weather,】】","to부정사 (형용사적) : power를 꾸밈"],["I {v|would} {a|make}","make + 목적어 + 동사원형"],["this rain stop.",""]]},{"no":"12","chunks":[{"en":"We wouldn’t have won","ko":"우리는 우승하지 못했을 것이다","k":"C","lab":"C 주절 wouldn’t have won","h":[["wouldn’t have won","c"]]},{"en":"if some of our players","ko":"우리 선수들 중 몇몇이","k":"S","lab":"S 주어"},{"en":"had quit earlier this year.","ko":"올해 초에 그만두었다면.","k":"V","lab":"V had quit (quit 아님)","h":[["had quit","v"]]}],"tr":"올해 초에 우리 선수들 중 몇몇이 그만두었다면 우리는 우승하지 못했을 것이다.","why":"주절의 동사가 <b>wouldn’t have won</b>(win: 이기다)이에요. would + have p.p.는 가정법 과거완료라서 if절은 <b>had quit</b>(quit: 그만두다)이 짝이에요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","주절","wouldn’t have won (would + have p.p.)"],["c","if절 동사","had quit (had p.p.)"]],"verb":{"ok":"had quit","no":"quit"},"note":{"t":"주절이 would have p.p.면 if절은 had p.p.","lines":["wouldn’t have won → had quit","과거 사실과 반대인 가정 → if절 had p.p."]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["We {v|wouldn’t have won}","주절 : would have p.p. 의 부정"],["【{c|if} some of our players",""],["{a|had quit} earlier this year.】","if절 : 가정법 과거완료"]]}],"cprompt":"맞는 동사를 고르세요"},{"id":"c05q2","page":61,"title":"문장 연습 밑줄","sub":"밑줄 친 부분 어법 고치기","prompt":"시제 단서(if절·주절)를 누르세요","pnote":{"t":"if절과 주절을 짝 지어 고치기","lines":["현재·미래 가능성은 if + 현재 → will / 현재 사실과 반대는 if + 과거 → would + 동사원형 / 과거 사실과 반대는 if + had p.p. → would + have p.p."]},"items":[{"no":"1","chunks":[{"en":"If people","ko":"사람들이","k":"S","lab":"S 주어"},{"en":"lived forever,","ko":"영원히 산다면,","k":"V","lab":"V lived (had lived 아님)","h":[["lived","v"]]},{"en":"the world would become","ko":"세상은 될 것이다","k":"C","lab":"C 주절 would become","h":[["would become","c"]]},{"en":"very crowded.","ko":"매우 붐비게.","k":"","lab":""}],"tr":"사람들이 영원히 산다면, 세상은 매우 붐비게 될 것이다.","why":"주절의 동사가 <b>would become</b>(become: 되다)이에요. would + 동사원형이면 가정법 과거예요. 영원히 사는 것은 가능성이 없는 일이라서 if절은 과거시제여야 해요. <b>had lived → lived</b>(live: 살다)로 고쳐요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","주절","would become (would + 동사원형)"],["c","if절 동사","had lived → lived"]],"verb":{"ok":"lived","no":"had lived"},"note":{"t":"주절이 would + 동사원형이면 if절은 과거","lines":["would become → lived","지금 사실과 반대인 가정 → if절 과거시제"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["【{c|If} people",""],["{a|lived} forever,】","if절 : 가정법 과거"],["the world {v|would become}",""],["very crowded.",""]]},{"no":"2","chunks":[{"en":"You may discover hidden talents","ko":"너는 숨겨진 재능을 발견할지도 모른다","k":"C","lab":"C 주절 may discover","h":[["may discover","c"]]},{"en":"if you","ko":"네가","k":"S","lab":"S 주어"},{"en":"try new hobbies.","ko":"새로운 취미를 시도해 보면.","k":"V","lab":"V try (tried 아님)","h":[["try","v"]]}],"tr":"만약 네가 새로운 취미를 시도해 보면 숨겨진 재능을 발견할지도 모른다.","why":"주절의 동사가 <b>may discover</b>(discover: 발견하다)예요. 새 취미를 해 보는 것은 실제로 일어날 수 있는 일(조건 부사절)이라서 if절은 현재시제여야 해요. <b>tried → try</b>(try: 시도하다)로 고쳐요.","ex":"<b>일어날 수 있는 일</b>(조건 부사절)은 if절에 <b>현재시제</b>를 써요. 주절은 will 등이에요. 미래의 일이어도 if절에는 will을 쓰지 않아요.","st":[["c","주절","may discover"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","tried → try"]],"verb":{"ok":"try","no":"tried"},"note":{"t":"주절이 may면 if절은 현재시제","lines":["may discover → try","일어날 수 있는 일 → if절은 현재시제"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["You {v|may discover} hidden talents",""],["【{c|if} you",""],["{a|try} new hobbies.】","조건절 : 현재형으로 미래 의미"]]},{"no":"3","chunks":[{"en":"He","ko":"그는","k":"S","lab":"S 주어"},{"en":"speaks","ko":"말한다","k":"C","lab":"C 주절 동사 speaks (현재)"},{"en":"as if I had said something wrong","ko":"마치 내가 틀린 무언가를 말했던 것처럼","k":"V","lab":"V had said (said 아님)","h":[["as if","c"],["had said","v"]]},{"en":"at the last meeting,","ko":"지난 회의에서,","k":"M","lab":"M 시간 단서 at the last meeting (더 앞선 시점)"},{"en":"although everyone thought I was right.","ko":"비록 모두가 내가 맞다고 생각했음에도.","k":"","lab":""}],"tr":"비록 모두가 내가 맞다고 생각했음에도, 그는 마치 내가 지난 회의에서 틀린 무언가를 말했던 것처럼 말한다.","why":"주절의 동사 <b>speaks</b>(speak: 말하다, 현재)는 현재예요. 그런데 틀린 말을 한 것은 <b>at the last meeting</b>(지난 회의에서)이라서 말하는 때보다 더 앞선 일이에요. 그래서 <b>said → had said</b>(say: 말하다)로 고쳐요.","ex":"뒤의 <b>although everyone thought I was right</b>(모두가 내가 맞다고 생각했지만 — think: 생각하다)가 &ldquo;틀린 말을 하지 않았다&rdquo;는 것을 알려 줘서 as if(마치 ~처럼)가 맞는 거예요.","st":[["v","주절 동사","speaks (현재)"],["m","시간 단서","at the last meeting (더 앞선 시점)"],["v","as if절","said → had said"]],"verb":{"ok":"had said","no":"said"},"note":{"t":"앞선 시점의 일은 as if + had p.p.","lines":["speaks, at the last meeting → had said","말하는 지금보다 지난 회의가 더 앞선다 → had p.p."]},"taps":[{"k":"M","t":"시간 단서를 누르세요"},{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["He",""],["{v|speaks}",""],["【{c|as if} I {a|had said} something wrong","as if + had p.p. : 마치 ~했던 것처럼"],["at the last meeting,】",""],["【{c|although} everyone {v|thought} 【I {v|was} right.】】","although : ~이지만 (양보의 접속사)"]]},{"no":"4","chunks":[{"en":"I","ko":"나는","k":"S","lab":"S 주어"},{"en":"would have visited you in London","ko":"런던에서 너를 방문했을 것이다","k":"V","lab":"V have visited (visit 아님)","h":[["would","c"],["have visited","v"]]},{"en":"if I had known","ko":"내가 알았다면","k":"C","lab":"C if절 동사 had known (had p.p.)","h":[["if","c"],["had known","c"]]},{"en":"you were staying there at that time.","ko":"네가 그 당시에 거기에 머무르는 중인 것을.","k":"","lab":""}],"tr":"그 당시에 네가 거기에 머무르는 중인 것을 알았다면 나는 런던에서 너를 방문했을 것이다.","why":"if절의 동사가 <b>had known</b>(know: 알다)이에요. had p.p.는 가정법 과거완료라서 주절은 would + <b>have p.p.</b>가 짝이에요. <b>visit → have visited</b>(visit: 방문하다)로 고쳐요. at that time(그 당시에)도 과거 단서예요.","ex":"<b>you were staying there</b> = 네가 거기에 머무르는 중이었다(be + -ing, 진행). stay는 &ldquo;머무르다&rdquo;예요.","st":[["c","if절 동사","had known (had p.p.)"],["c","주절","would + have p.p."],["v","동사","visit → have visited"]],"verb":{"ok":"have visited","no":"visit"},"note":{"t":"if절이 had p.p.면 주절은 would have p.p.","lines":["had known → would have visited","과거 사실과 반대인 가정 → would + have p.p."]},"taps":[{"k":"C","t":"if절 동사를 누르세요"}],"sx":[["I",""],["{v|would} {a|have visited} you in London","주절 : would have p.p."],["【{c|if} I {v|had known}","if절 : 가정법 과거완료"],["【you {v|were staying} there at that time.】】","명사절 : known의 목적어 (that 생략)"]]},{"no":"5","chunks":[{"en":"If diamonds","ko":"다이아몬드가","k":"S","lab":"S 주어"},{"en":"grew on trees like apples,","ko":"사과와 같이 나무에서 자란다면,","k":"C","lab":"C if절 동사 grew (과거시제)","h":[["grew","c"]]},{"en":"we could find","ko":"우리는 찾을 수 있을 것이다","k":"V","lab":"V find (have found 아님)","h":[["could","c"],["find","v"]]},{"en":"them easily and quickly.","ko":"그것들을 쉽고 빠르게.","k":"","lab":""}],"tr":"다이아몬드가 사과와 같이 나무에서 자란다면, 우리는 쉽고 빠르게 그것들을 찾을 수 있을 것이다.","why":"if절의 동사가 과거시제 <b>grew</b>(grow: 자라다)예요. 가정법 과거라서 주절은 could + <b>동사원형</b>이 짝이에요. <b>have found → find</b>(find: 찾다)로 고쳐요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","grew (과거시제)"],["c","주절","could + 동사원형"],["v","동사","have found → find"]],"verb":{"ok":"find","no":"have found"},"note":{"t":"if절이 과거면 could + 동사원형","lines":["grew → could find","지금 사실과 반대인 가정 → could 뒤에 동사원형"]},"taps":[{"k":"C","t":"if절 동사를 누르세요"}],"sx":[["【{c|If} diamonds",""],["{v|grew} on trees like apples,】","if절 : 가정법 과거"],["we {v|could} {a|find}",""],["them easily {c|and} quickly.","병렬 : 부사 두 개 연결"]]},{"no":"6","chunks":[{"en":"Only 50 years ago,","ko":"불과 50년 전만 해도,","k":"M","lab":"M 과거 시간 단서 Only 50 years ago"},{"en":"if you","ko":"당신이","k":"S","lab":"S 주어"},{"en":"had said the word “algorithms,”","ko":"‘알고리즘’이라는 단어를 말했다면,","k":"V","lab":"V had said (said 아님)","h":[["had said","v"]]},{"en":"most people would have asked,","ko":"대부분의 사람들이 물었을 것이다,","k":"C","lab":"C 주절 would have asked","h":[["would have asked","c"]]},{"en":"“Pardon?”","ko":"‘뭐라고요?’라고.","k":"","lab":""}],"tr":"불과 50년 전만 해도, 당신이 ‘알고리즘’이라는 단어를 말했다면, 대부분의 사람들이 ‘뭐라고요?’라고 물었을 것이다.","why":"주절의 동사가 <b>would have asked</b>(ask: 묻다)예요. would + have p.p.는 가정법 과거완료라서 if절은 <b>had p.p.</b>가 짝이에요. <b>said → had said</b>(say: 말하다)로 고쳐요. Only 50 years ago(불과 50년 전)가 과거 단서예요.","ex":"<b>Pardon?</b>은 &ldquo;뭐라고요?&rdquo;라고 되묻는 말이에요.","st":[["m","시간 단서","Only 50 years ago"],["c","주절","would have asked"],["c","if절 동사","said → had said"]],"verb":{"ok":"had said","no":"said"},"note":{"t":"주절이 would have p.p.면 if절은 had p.p.","lines":["would have asked → had said","과거 사실과 반대인 가정 → if절 had p.p."]},"taps":[{"k":"M","t":"시간 단서를 누르세요"},{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["Only 50 years ago,",""],["【{c|if} you",""],["{a|had said} the word “algorithms,”】","if절 : 가정법 과거완료"],["most people {v|would have asked},","주절 : would have p.p."],["“Pardon?”",""]]},{"no":"7","chunks":[{"en":"If she","ko":"그녀가","k":"S","lab":"S 주어"},{"en":"reveals new information about black holes,","ko":"블랙홀에 대한 새로운 정보를 밝힌다면,","k":"V","lab":"V reveals (revealed 아님, 이미 맞음)","h":[["reveals","v"]]},{"en":"the scientific community will be","ko":"과학계는 ~일 것이다","k":"C","lab":"C 주절 will be","h":[["will be","c"]]},{"en":"surprised.","ko":"놀랄.","k":"","lab":""}],"tr":"만약 그녀가 블랙홀에 대한 새로운 정보를 밝힌다면, 과학계는 놀랄 것이다.","why":"주절의 동사가 <b>will be</b>예요. 새로운 정보를 밝히는 것은 일어날 수 있는 일(조건 부사절)이라서 if절은 현재시제 <b>reveals</b>(reveal: 밝히다)가 맞아요. 고칠 곳이 없어요.","ex":"<b>be surprised</b> = 놀라다. <b>the scientific community</b>는 &ldquo;과학계&rdquo;예요.","st":[["c","주절","will be"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","reveals (맞음)"]],"verb":{"ok":"reveals","no":"revealed"},"note":{"t":"주절이 will이면 if절은 현재시제","lines":["will be → reveals (맞음)","일어날 수 있는 일 → if절 현재시제. 고칠 곳 없음(○)"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["【{c|If} she",""],["{a|reveals} new information about black holes,】","조건절 : 현재형으로 미래 의미"],["the scientific community {v|will be}",""],["surprised.",""]]},{"no":"8","chunks":[{"en":"Agatha","ko":"아가사는","k":"S","lab":"S 주어"},{"en":"nodded her head","ko":"고개를 끄덕였다","k":"C","lab":"C 주절 동사 nodded (과거)","h":[["nodded","c"]]},{"en":"as if she understood the instructions,","ko":"마치 지시를 이해한 것처럼,","k":"V","lab":"V understood (understands 아님, 이미 맞음)","h":[["as if","c"],["understood","v"]]},{"en":"but she clearly did not.","ko":"하지만 그녀는 분명히 이해하지 못했다.","k":"","lab":""}],"tr":"Agatha는 마치 지시를 이해한 것처럼 고개를 끄덕였지만, 분명히 이해하지 못했다.","why":"주절의 동사 <b>nodded</b>(nod: 끄덕이다의 과거형)와 지시를 이해한 것처럼 하는 때가 같아요. 같은 시점이라서 as if절에 과거시제 <b>understood</b>(understand: 이해하다)가 맞아요. 고칠 곳이 없어요.","ex":"<b>but she clearly did not</b>에서 did not 뒤에는 understand the instructions가 생략됐어요(CH04 POINT 3: did는 일반동사를 대신해요).","st":[["v","주절 동사","nodded (과거)"],["v","as if절","understood (같은 시점, 맞음)"]],"verb":{"ok":"understood","no":"understands"},"note":{"t":"as if절은 주절과 같은 시점이면 과거","lines":["nodded → understood (맞음)","끄덕인 때와 같은 때의 일 → 과거. 고칠 곳 없음(○)"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["Agatha",""],["{v|nodded} her head",""],["【{c|as if} she {a|understood} the instructions,】","as if + 가정법 과거 : 마치 ~인 것처럼"],["{c|but} she clearly {v|did} not.","대동사 did : understand 대신 쓴 말"]]},{"no":"9","chunks":[{"en":"There would be less traffic on the road","ko":"도로에 더 적은 교통량이 있을 것이다","k":"C","lab":"C 주절 would be","h":[["would be","c"]]},{"en":"if more people","ko":"더 많은 사람들이","k":"S","lab":"S 주어"},{"en":"rode bicycles or subways.","ko":"자전거나 지하철을 탄다면.","k":"V","lab":"V rode (ride 아님)","h":[["rode","v"]]}],"tr":"더 많은 사람들이 자전거나 지하철을 탄다면 도로의 교통량이 더 적을 것이다.","why":"주절의 동사가 <b>would be</b>예요. 가정법 과거(지금 사실의 반대)라서 if절은 과거시제여야 해요. <b>ride → rode</b>(ride: 타다)로 고쳐요.","ex":"<b>less traffic</b> = 더 적은 교통량. traffic은 셀 수 없는 명사라서 less를 써요.","st":[["c","주절","would be (would + 동사원형)"],["c","if절 동사","ride → rode"]],"verb":{"ok":"rode","no":"ride"},"note":{"t":"주절이 would + 동사원형이면 if절은 과거","lines":["would be → rode","지금 사실과 반대인 가정 → if절 과거시제"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["There {v|would be} less traffic on the road",""],["【{c|if} more people",""],["{a|rode} bicycles {c|or} subways.】","병렬 : bicycles와 subways 연결"]]},{"no":"10","chunks":[{"en":"If the invention of the printing press","ko":"인쇄기의 발명이","k":"S","lab":"S 주어"},{"en":"had not occurred,","ko":"일어나지 않았다면,","k":"C","lab":"C if절 동사 had not occurred (had p.p.)","h":[["had not occurred","c"]]},{"en":"the spread of knowledge","ko":"지식의 확산은","k":"","lab":""},{"en":"would have been much slower","ko":"훨씬 더 느렸을 것이다","k":"V","lab":"V have been (be 아님)","h":[["would","c"],["have been","v"]]},{"en":"throughout history.","ko":"역사를 통틀어.","k":"","lab":""}],"tr":"인쇄기의 발명이 일어나지 않았다면, 역사를 통틀어 지식의 확산은 훨씬 더 느렸을 것이다.","why":"if절의 동사가 <b>had not occurred</b>(occur: 일어나다)예요. had p.p.는 가정법 과거완료라서 주절은 would + <b>have p.p.</b>가 짝이에요. <b>be → have been</b>(be: ~이다)으로 고쳐요. throughout history(역사 내내)는 과거 이야기예요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","had not occurred (had p.p.)"],["c","주절","would + have p.p."],["v","동사","be → have been"]],"verb":{"ok":"have been","no":"be"},"note":{"t":"if절이 had p.p.면 주절은 would have p.p.","lines":["had not occurred → would have been","과거 사실과 반대인 가정 → would + have p.p."]},"taps":[{"k":"C","t":"if절 동사를 누르세요"}],"sx":[["【{c|If} the invention of the printing press",""],["{v|had not occurred},】","if절 : 가정법 과거완료"],["the spread of knowledge",""],["{v|would} {a|have been} much slower","주절 : would have p.p."],["throughout history.",""]]},{"no":"11","chunks":[{"en":"If you","ko":"당신이","k":"S","lab":"S 주어"},{"en":"never drive a car yourself,","ko":"스스로 차를 결코 운전하지 않는다면,","k":"V","lab":"V drive (drove 아님)","h":[["never","c"],["drive","v"]]},{"en":"you will never learn","ko":"당신은 결코 배우지 못할 것이다","k":"C","lab":"C 주절 will never learn","h":[["will never learn","c"]]},{"en":"driving because it requires experience to improve.","ko":"나아지기 위해서는 경험이 필요하기 때문에 운전을.","k":"","lab":""}],"tr":"만약 당신이 스스로 차를 운전하지 않는다면, 나아지기 위해서는 경험이 필요하기 때문에 당신은 운전을 결코 배우지 못할 것이다.","why":"주절의 동사가 <b>will never learn</b>(learn: 배우다)이에요. 운전을 안 하면 못 배운다는 것은 일어날 수 있는 일(조건 부사절)이라서 if절은 현재시제여야 해요. <b>drove → drive</b>(drive: 운전하다)로 고쳐요.","ex":"<b>일어날 수 있는 일</b>(조건 부사절)은 if절에 <b>현재시제</b>를 써요. 주절은 will 등이에요. 미래의 일이어도 if절에는 will을 쓰지 않아요.","st":[["c","주절","will never learn"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","drove → drive"]],"verb":{"ok":"drive","no":"drove"},"note":{"t":"주절이 will이면 if절은 현재시제","lines":["will never learn → drive","일어날 수 있는 일 → if절은 현재시제"]},"taps":[{"k":"C","t":"주절 동사를 누르세요"}],"sx":[["【{c|If} you",""],["never {a|drive} a car yourself,】","조건절 : 현재형으로 미래 의미"],["you {v|will never learn}",""],["{p|driving} 【{c|because} it {v|requires} experience 【{p|to} improve】】.","because : ~ 때문에 (이유)"]]},{"no":"12","chunks":[{"en":"I would cook at home more often","ko":"나는 더 자주 집에서 요리할 것이다","k":"V","lab":"V cook (have cooked 아님)","h":[["would","c"],["cook","v"]]},{"en":"if the kitchen in my apartment","ko":"내 아파트의 부엌이","k":"","lab":""},{"en":"were bigger.","ko":"더 크다면.","k":"C","lab":"C if절 동사 were (과거시제)","h":[["were","c"]]}],"tr":"내 아파트의 부엌이 더 크다면 나는 더 자주 집에서 요리할 것이다.","why":"if절의 동사가 과거시제 <b>were</b>(be: ~이다)예요. 가정법 과거라서 주절은 would + <b>동사원형</b>이 짝이에요. <b>have cooked → cook</b>(cook: 요리하다)으로 고쳐요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","were (과거시제)"],["c","주절","would + 동사원형"],["v","동사","have cooked → cook"]],"verb":{"ok":"cook","no":"have cooked"},"note":{"t":"if절이 과거면 would + 동사원형","lines":["were → would cook","지금 사실과 반대인 가정 → would 뒤에 동사원형"]},"taps":[{"k":"C","t":"if절 동사를 누르세요"}],"sx":[["I {v|would} {a|cook} at home more often",""],["【{c|if} the kitchen in my apartment",""],["{v|were} bigger.】","if절 : 가정법 과거"]]}],"cprompt":"바르게 고친 말을 고르세요"},{"id":"c05s1","page":62,"title":"짧은 지문 연습 제대로","sub":"각 네모 안에서 어법에 맞는 표현 고르기 · 틀린 것 찾기","prompt":"if절·as if절의 단서를 누르세요","pnote":{"t":"지문에서도 if절 먼저 보기","lines":["if절 동사의 시제를 보고 가능성(현재형), 지금 사실과 반대(과거형), 지난 일과 반대(had p.p.)를 구분한다","as if절은 주절 동사와 같은 시점이면 과거형, 더 앞선 시점이면 had p.p."]},"items":[{"no":"1-(A)","chunks":[{"en":"If someone (A)","ko":"만약 누군가가","k":"C","lab":"C if절 시작"},{"en":"were able to read other people’s minds,","ko":"다른 사람들의 마음을 읽을 수 있다면,","k":"V","lab":"V were (had been 아님)"},{"en":"would he or she still get along with friends and family?","ko":"그 또는 그녀는 여전히 친구들 그리고 가족들과 잘 지낼 수 있었을까?","k":"C","lab":"C would + 동사원형 주절"}],"tr":"누군가가 다른 사람들의 마음을 읽을 수 있다면, 그 또는 그녀는 여전히 친구들 그리고 가족들과 잘 지낼 수 있었을까?","why":"주절이 <b>would he or she still get along</b>(would + 동사원형)예요. 다른 사람의 마음을 읽는 것은 가능성이 없는 일이라서 가정법 과거이고, if절은 과거시제 <b>were</b>(be: ~이다)가 짝이에요.","ex":"<b>be able to V</b> = V할 수 있다. <b>get along with ~</b> = ~와 잘 지내다.","st":[["c","주절","would + 동사원형"],["c","가능성","가능성 없는 일"],["c","if절 동사","were (과거시제)"]],"verb":{"ok":"were","no":"had been"},"note":{"t":"if절 were는 지금 사실과 반대","lines":["If someone were + would he or she ~","주절이 would + 동사원형이라 if절은 과거형 were(had been 아님)"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"<u>If someone (A) were / had been able to read other people’s minds, would he or she still get along with friends and family?</u> Absolutely not. If people (B) know / knew too much about other people’s thoughts, their relationships may become difficult.","pts":["5.1"],"sx":[["【{c|If} someone (A)",""],["{a|were} able {p|to} read other people’s minds,】","be able to + 동사원형 : ~할 수 있다"],["{v|would} he or she still {v|get along} with friends and family?","get along with : ~와 잘 지내다"]]},{"no":"1-2","chunks":[{"en":"Absolutely","ko":"절대로","k":"C","lab":"C 앞 문장을 받는 부사"},{"en":"not.","ko":"그렇지 않다.","k":"V","lab":"V not (이미 맞음)"}],"tr":"절대로 그렇지 않다.","why":"","ex":"","st":[],"verb":{"ok":"not","no":"nothing"},"note":{"t":"앞 문장에 이어지는 짧은 대답","lines":["Absolutely not.","가정법 문제가 아니라 앞뒤 문장을 이어 주는 부분이다"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"If someone (A) were / had been able to read other people’s minds, would he or she still get along with friends and family? <u>Absolutely not.</u> If people (B) know / knew too much about other people’s thoughts, their relationships may become difficult.","sx":[["Absolutely",""],["{a|not}.",""]]},{"no":"1-(B)","chunks":[{"en":"If people (B)","ko":"만약 사람들이","k":"C","lab":"C if절 시작"},{"en":"know too much about other people’s thoughts,","ko":"다른 사람들의 생각에 대해 너무 많이 알게 된다면,","k":"V","lab":"V know (knew 아님)"},{"en":"their relationships may become difficult.","ko":"그들의 관계는 어려워질지도 모른다.","k":"C","lab":"C may 주절"}],"tr":"만약 사람들이 다른 사람들의 생각에 대해 너무 많이 알게 된다면, 그들의 관계는 어려워질지도 모른다.","why":"주절의 동사가 <b>may become</b>(become: 되다)이에요. 이번에는 정말 일어날 수 있는 일(조건 부사절)이라서 if절에 현재시제 <b>know</b>(know: 알다)가 맞아요. 앞 문장(가능성 없는 일)과 구분하세요.","ex":"<b>일어날 수 있는 일</b>(조건 부사절)은 if절에 <b>현재시제</b>를 써요. 주절은 will 등이에요. 미래의 일이어도 if절에는 will을 쓰지 않아요.","st":[["c","주절","may become"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","know (현재시제)"]],"verb":{"ok":"know","no":"knew"},"note":{"t":"일어날 수 있는 일은 if절 현재형","lines":["If people know + may become","주절이 may become이라 일어날 수 있는 일, if절은 현재형 know"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"If someone (A) were / had been able to read other people’s minds, would he or she still get along with friends and family? Absolutely not. <u>If people (B) know / knew too much about other people’s thoughts, their relationships may become difficult.</u>","pts":["5.2"],"sx":[["【{c|If} people (B)",""],["{a|know} too much about other people’s thoughts,】","조건절 : 현재형으로 미래 의미"],["their relationships {v|may become} difficult.",""]]},{"no":"2-(A)","chunks":[{"en":"If you (A)","ko":"만약 당신이","k":"C","lab":"C if절 시작"},{"en":"look closely at the history of the world,","ko":"세계의 역사를 자세히 보면,","k":"V","lab":"V look (looked 아님)"},{"en":"you will find some inventions that have changed history forever.","ko":"당신은 역사를 영원히 바꾸어 놓은 몇몇 발명품들을 발견할 것이다.","k":"C","lab":"C will 주절"}],"tr":"당신이 세계의 역사를 자세히 보면, 역사를 영원히 바꾸어 놓은 몇몇 발명품들을 발견할 수 있을 것이다.","why":"주절의 동사가 <b>will find</b>(find: 발견하다)예요. 역사를 자세히 보는 것은 일어날 수 있는 일(조건 부사절)이라서 if절은 현재시제 <b>look</b>(look: 보다)이 맞아요.","ex":"<b>that have changed history forever</b>에서 that은 inventions를 꾸며 줘요. (change: 바꾸다)","st":[["c","주절","will find"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","look (현재시제)"]],"verb":{"ok":"look","no":"looked"},"note":{"t":"조건 부사절은 현재형","lines":["If you look + you will find","주절이 will find라 실제로 일어날 수 있는 일, if절은 현재형 look"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"<u>If you (A) look / looked closely at the history of the world, you will find some inventions that have changed history forever.</u> For example, the result of World War II might (B) be / have been different if the atomic bomb had not been developed.","pts":["5.2"],"sx":[["【{c|If} you (A)",""],["{a|look} closely at the history of the world,】","조건절 : 현재형으로 미래 의미"],["you {v|will find} some inventions 【{c|that} {v|have changed} history forever】.","주격 관계대명사절 : inventions를 꾸밈"]]},{"no":"2-(B)","chunks":[{"en":"For example, the result of World War II","ko":"예를 들어, 제2차 세계 대전의 결과는","k":"S","lab":"S 주어"},{"en":"might (B) have been different","ko":"달랐을지도 모른다","k":"V","lab":"V have been (be 아님)"},{"en":"if the atomic bomb had not been developed.","ko":"만약 원자폭탄이 개발되지 않았다면.","k":"C","lab":"C had p.p. (과거완료 if절)"}],"tr":"예를 들어, 만약 원자폭탄이 개발되지 않았다면, 제2차 세계 대전의 결과는 달랐을지도 모른다.","why":"if절의 동사가 <b>had not been developed</b>(develop: 개발하다)예요. had p.p.는 가정법 과거완료라서 주절은 might + <b>have p.p.</b>인 <b>have been</b>(be: ~이다)이 짝이에요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","had not been developed (had p.p.)"],["c","주절","might + have p.p."],["v","동사","have been"]],"verb":{"ok":"have been","no":"be"},"note":{"t":"had p.p.와 짝은 might have p.p.","lines":["if ~ had not been developed + might have been","지난 일과 반대라서 if절 had p.p.와 짝인 주절은 might have p.p."]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"If you (A) look / looked closely at the history of the world, you will find some inventions that have changed history forever. <u>For example, the result of World War II might (B) be / have been different if the atomic bomb had not been developed.</u>","pts":["5.1"],"sx":[["For example, the result of World War II",""],["{v|might} (B) {a|have been} different","might have p.p. : 과거 추측"],["【{c|if} the atomic bomb {v|had not been developed}.】","if절 : 가정법 과거완료 (수동)"]]},{"no":"3-(A)","chunks":[{"en":"Too many companies advertise their products","ko":"너무 많은 회사들이 그들의 제품을 광고한다","k":"","lab":""},{"en":"as if they (A)","ko":"마치 그들이","k":"C","lab":"C as if 단서"},{"en":"had no competitors.","ko":"경쟁자가 없는 것처럼.","k":"V","lab":"V had (had had 아님)"}],"tr":"너무 많은 회사들이 마치 그들이 경쟁자가 없는 것처럼 그들의 제품을 광고한다.","why":"주절의 동사 <b>advertise</b>(advertise: 광고하다, 현재)와 경쟁자가 없는 때가 같아요. 같은 시점이라서 as if절에 과거시제 <b>had</b>(have: 가지다)가 맞아요.","ex":"<b>no competitors</b>(경쟁자가 없는)처럼 상상하는 것이라서 사실은 경쟁자가 있다는 뜻이에요. 사실과 반대!","st":[["v","주절 동사","advertise (현재)"],["v","as if절","had (같은 시점)"]],"verb":{"ok":"had","no":"had had"},"note":{"t":"as if절은 주절과 같은 시점이면 과거형","lines":["advertise + as if they had","광고하는 것도 지금이라 같은 시점이다. 과거형 had(had had 아님)"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"<u>Too many companies advertise their products as if they (A) had / had had no competitors.</u> If there were no competitors in the market, those companies would (B) survive / have survived, but that rarely happens in reality.","pts":["5.3"],"sx":[["Too many companies {v|advertise} their products",""],["【{c|as if} they (A)",""],["{a|had} no competitors.】","as if + 가정법 과거 : 마치 ~인 것처럼"]]},{"no":"3-(B)","chunks":[{"en":"If there were no competitors in the market,","ko":"시장에 경쟁자가 없다면,","k":"C","lab":"C if절 were (과거시제)"},{"en":"those companies","ko":"그런 회사들이","k":"S","lab":"S 주어"},{"en":"would (B) survive,","ko":"살아남을 것이지만,","k":"V","lab":"V survive (have survived 아님)"},{"en":"but that rarely happens in reality.","ko":"현실에서 그런 일은 거의 일어나지 않는다.","k":"","lab":""}],"tr":"시장에 경쟁자가 없다면, 그런 회사들이 살아남을 것이지만, 현실에서 그런 일은 거의 일어나지 않는다.","why":"if절의 동사가 과거시제 <b>were</b>(be: ~이다)예요. 가정법 과거라서 주절은 would + 동사원형인 <b>survive</b>(survive: 살아남다)가 짝이에요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","were (과거시제)"],["c","주절","would + 동사원형"],["v","동사","survive"]],"verb":{"ok":"survive","no":"have survived"},"note":{"t":"if절 were와 짝은 would + 동사원형","lines":["If there were ~ + would survive","if절이 과거형 were라 지금 사실과 반대. 주절은 would + 동사원형"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"Too many companies advertise their products as if they (A) had / had had no competitors. <u>If there were no competitors in the market, those companies would (B) survive / have survived, but that rarely happens in reality.</u>","pts":["5.1"],"sx":[["【{c|If} there {v|were} no competitors in the market,】","if절 : 가정법 과거"],["those companies",""],["{v|would} (B) {a|survive},","주절 : would + 동사원형"],["{c|but} that rarely {v|happens} in reality.",""]]},{"no":"4-①","chunks":[{"en":"If Amy hadn’t avoided last week’s interview","ko":"만약 에이미가 지난주의 면접을 피하지 않았다면,","k":"C","lab":"C had p.p. (과거완료 if절)"},{"en":"because of her fear of failure,","ko":"실패에 대한 두려움 때문에,","k":"","lab":""},{"en":"she might have gotten her dream job.","ko":"그녀는 자신이 꿈꾸던 직업을 얻었을지도 모른다.","k":"V","lab":"V have gotten (get 아님)"}],"tr":"Amy가 실패에 대한 두려움 때문에 지난주의 면접을 피하지 않았다면, 그녀는 자신이 꿈꾸던 직업을 얻었을지도 모른다.","why":"if절의 동사가 <b>hadn’t avoided</b>(avoid: 피하다)예요. had p.p.는 가정법 과거완료라서 주절은 might + <b>have p.p.</b>가 짝이에요. <b>get → have gotten</b>(get: 얻다)으로 고쳐요. last week(지난주)도 과거 단서예요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","hadn’t avoided (had p.p.)"],["c","주절","might + have p.p."],["v","동사","get → have gotten"]],"verb":{"ok":"have gotten","no":"get"},"note":{"t":"if절 had p.p.와 짝은 might have p.p.","lines":["hadn’t avoided + might have gotten","지난 일과 반대라서 get이 아니라 have gotten으로 고친다"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"<u>If Amy hadn’t avoided last week’s interview because of her fear of failure, she might ① get her dream job.</u> You will achieve much more in life if you ② accept that failure is sometimes normal.","pts":["5.1"],"sx":[["【{c|If} Amy {v|hadn’t avoided} last week’s interview",""],["because of her fear of failure,】","because of + 명사 : ~ 때문에"],["she {v|might} {a|have gotten} her dream job.","주절 : might have p.p."]]},{"no":"4-②","chunks":[{"en":"You will achieve much more in life","ko":"당신은 인생에서 훨씬 더 많은 것을 성취할 것이다","k":"C","lab":"C will 주절"},{"en":"if you","ko":"만약 당신이","k":"C","lab":"C 조건 if절 단서"},{"en":"accept that failure is sometimes normal.","ko":"실패가 때때로 정상적이라는 것을 받아들인다면.","k":"V","lab":"V accept (이미 맞음)"}],"tr":"만약 당신이 실패가 때때로 정상적이라는 것을 받아들인다면 당신은 인생에서 훨씬 더 많은 것을 성취할 것이다.","why":"주절의 동사가 <b>will achieve</b>예요. 실패를 받아들이면 더 이룬다는 것은 일어날 수 있는 일(조건 부사절)이라서 if절은 현재시제 <b>accept</b>(accept: 받아들이다)가 맞아요.","ex":"<b>일어날 수 있는 일</b>(조건 부사절)은 if절에 <b>현재시제</b>를 써요. 주절은 will 등이에요. 미래의 일이어도 if절에는 will을 쓰지 않아요.","st":[["c","주절","will achieve"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","accept (현재시제)"]],"verb":{"ok":"accept","no":"accepted"},"note":{"t":"조건 부사절은 현재형","lines":["will achieve + if you accept","주절이 will이라 일어날 수 있는 일, if절은 현재형 accept(이미 맞음)"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"If Amy hadn’t avoided last week’s interview because of her fear of failure, she might ① get her dream job. <u>You will achieve much more in life if you ② accept that failure is sometimes normal.</u>","pts":["5.2"],"sx":[["You {v|will achieve} much more in life",""],["【{c|if} you",""],["{a|accept} 【{c|that} failure {v|is} sometimes normal】.】","that절 : accept의 목적어 (명사절)"]]},{"no":"5-①","chunks":[{"en":"Thomas speaks Chinese","ko":"토머스는 중국어를 말한다","k":"","lab":""},{"en":"as if he","ko":"마치 그가","k":"C","lab":"C as if 단서"},{"en":"had learned it when he was young,","ko":"어렸을 때 그것을 배웠던 것처럼,","k":"V","lab":"V had learned (learned 아님)"},{"en":"but he only learned it recently.","ko":"하지만 그는 최근에야 그것을 배웠다.","k":"","lab":""}],"tr":"Thomas는 마치 그가 어렸을 때 배웠던 것처럼 중국어를 말하지만, 그는 최근에야 그것을 배웠다.","why":"주절의 동사 <b>speaks</b>(speak: 말하다, 현재)는 현재예요. 어렸을 때 배운 것은 말하는 때보다 더 앞선 일이에요. 그래서 <b>learned → had learned</b>(learn: 배우다)로 고쳐요. 뒤의 he only learned it recently(최근에야 배웠다)가 &ldquo;사실은 어릴 때 배우지 않았다&rdquo;를 알려 줘요.","ex":"<b>as if</b>: 주절과 같은 때의 일이면 <b>과거시제</b>(be동사는 were), 주절보다 더 앞선 일이면 <b>had p.p.</b>","st":[["v","주절 동사","speaks (현재)"],["m","시간 단서","when he was young (더 앞선 시점)"],["v","as if절","learned → had learned"]],"verb":{"ok":"had learned","no":"learned"},"note":{"t":"더 앞선 시점이면 as if절 had p.p.","lines":["as if he + had learned","어렸을 때는 말하는 지금보다 앞선 일이라 learned를 had learned로 고친다"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"<u>Thomas speaks Chinese as if he ① learned it when he was young, but he only learned it recently.</u> He has a great talent for languages, so if he ② had chosen a language other than Chinese, he would have mastered it very quickly, too.","pts":["5.3"],"sx":[["Thomas {v|speaks} Chinese",""],["【{c|as if} he",""],["{a|had learned} it 【{c|when} he {v|was} young】,】","as if + had p.p. : 마치 ~했던 것처럼"],["{c|but} he only {v|learned} it recently.",""]]},{"no":"5-②","chunks":[{"en":"He has a great talent for languages,","ko":"그는 언어에 뛰어난 재능을 가지고 있어서,","k":"","lab":""},{"en":"so if he","ko":"그래서 만약 그가","k":"C","lab":"C if절 단서"},{"en":"had chosen a language other than Chinese,","ko":"중국어가 아닌 언어를 선택했다면,","k":"V","lab":"V had chosen (chose 아님)"},{"en":"he would have mastered it very quickly, too.","ko":"그는 그것 역시 매우 빨리 익혔을 것이다.","k":"C","lab":"C would have p.p. 주절"}],"tr":"그는 언어에 뛰어난 재능을 가지고 있어서, 그가 중국어가 아닌 언어를 선택했다면, 그것 역시 매우 빨리 익혔을 것이다.","why":"주절의 동사가 <b>would have mastered</b>(master: 완전히 익히다)예요. would + have p.p.는 가정법 과거완료라서 if절의 <b>had chosen</b>(choose: 선택하다)은 짝이 맞아요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","주절","would have mastered (would + have p.p.)"],["c","if절 동사","had chosen (had p.p.)"]],"verb":{"ok":"had chosen","no":"chose"},"note":{"t":"had chosen은 would have p.p.와 짝","lines":["if he had chosen + would have mastered","지난 일과 반대라서 if절 had p.p., 주절 would have p.p.(이미 맞음)"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"Thomas speaks Chinese as if he ① learned it when he was young, but he only learned it recently. <u>He has a great talent for languages, so if he ② had chosen a language other than Chinese, he would have mastered it very quickly, too.</u>","pts":["5.1"],"sx":[["He {v|has} a great talent for languages,",""],["{c|so} 【{c|if} he",""],["{a|had chosen} a language other than Chinese,】","if절 : 가정법 과거완료"],["he {v|would have mastered} it very quickly, too.",""]]},{"no":"6-①","chunks":[{"en":"If more students knew","ko":"만약 더 많은 학생들이 안다면,","k":"C","lab":"C if절 knew (과거시제)"},{"en":"that their present efforts could change their future,","ko":"그들의 현재의 노력이 그들의 미래를 바꿀 수 있다는 것을,","k":"","lab":""},{"en":"they would focus on their current studies,","ko":"그들은 자신의 현재 공부에 집중할 것이지만,","k":"V","lab":"V focus (focused 아님)"},{"en":"but it’s a pity that they don’t know it.","ko":"그들이 그것을 모른다는 것이 안타깝다.","k":"","lab":""}],"tr":"더 많은 학생들이 현재의 노력이 그들의 미래를 바꿀 수 있다는 것을 안다면, 그들은 자신의 현재 공부에 집중할 것이지만, 그들이 그것을 모른다는 것이 안타깝다.","why":"if절의 동사가 과거시제 <b>knew</b>(know: 알다)예요. 가정법 과거라서 주절은 would + 동사원형인 <b>focus</b>(focus: 집중하다)가 맞아요. 뒤의 it’s a pity that they don’t know it(모른다는 것이 안타깝다)이 &ldquo;지금 사실과 반대&rdquo;라는 걸 알려 줘요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","knew (과거시제)"],["c","주절","would + 동사원형"],["v","동사","focus"]],"verb":{"ok":"focus","no":"focused"},"note":{"t":"if절 knew와 짝은 would + 동사원형","lines":["If ~ knew + would focus","if절이 과거형 knew라 주절은 would + 동사원형 focus(이미 맞음)"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"<u>If more students knew that their present efforts could change their future, they would ① focus on their current studies, but it’s a pity that they don’t know it.</u> Students will have better options for deciding their future career paths if they ② performed better in school at the moment.","pts":["5.1"],"sx":[["【{c|If} more students {v|knew}",""],["【{c|that} their present efforts {v|could change} their future,】】","that절 : knew의 목적어 (명사절)"],["they {v|would} {a|focus} on their current studies,","가정법 과거 : 현재 사실과 반대"],["{c|but} it{v|’s} a pity 【{c|that} they {v|don’t know} it】.","가주어 it + 진주어 that절"]]},{"no":"6-②","chunks":[{"en":"Students","ko":"학생들은","k":"S","lab":"S 주어"},{"en":"will have better options for deciding their future career paths","ko":"미래 진로를 결정하는 데 더 나은 선택지를 갖게 될 것이다","k":"C","lab":"C will 주절"},{"en":"if they","ko":"만약 그들이","k":"C","lab":"C 조건 if절 단서"},{"en":"perform better in school at the moment.","ko":"지금 학교에서 더 잘 성취한다면.","k":"V","lab":"V perform (performed 아님)"}],"tr":"지금 학교에서 더 잘 성취한다면 학생들은 미래 진로를 결정하는 데 더 나은 선택지를 갖게 될 것이다.","why":"주절의 동사가 <b>will have</b>예요. at the moment(지금)에 더 잘하면 선택지가 늘어난다는 것은 일어날 수 있는 일(조건 부사절)이라서 if절은 현재시제여야 해요. <b>performed → perform</b>(perform: 해내다, 성취하다)으로 고쳐요.","ex":"<b>일어날 수 있는 일</b>(조건 부사절)은 if절에 <b>현재시제</b>를 써요. 주절은 will 등이에요. 미래의 일이어도 if절에는 will을 쓰지 않아요.","st":[["c","주절","will have"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","performed → perform"]],"verb":{"ok":"perform","no":"performed"},"note":{"t":"조건 부사절은 현재형","lines":["will have + if they perform","주절이 will이라 일어날 수 있는 일, performed를 perform으로 고친다"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"If more students knew that their present efforts could change their future, they would ① focus on their current studies, but it’s a pity that they don’t know it. <u>Students will have better options for deciding their future career paths if they ② performed better in school at the moment.</u>","pts":["5.2"],"sx":[["Students",""],["{v|will have} better options for {p|deciding} their future career paths","전치사 + 동명사"],["【{c|if} they",""],["{a|perform} better in school at the moment.】","조건절 : 현재형으로 미래 의미"]]}],"cprompt":"맞는 동사를 고르세요"},{"id":"c05s2","page":63,"title":"내신 서술형 대비 제대로","sub":"조건에 맞게 문장 쓰기 · 틀린 곳 고쳐 쓰기","prompt":"if절·as if절의 단서를 누르세요","pnote":{"t":"쓰는 문제도 if절부터","lines":["if절 동사의 시제로 가정법 과거, 가정법 과거완료, 조건 부사절을 먼저 가려낸다","주절은 would, could, might + 동사원형 또는 have p.p.로 짝을 맞춘다"]},"items":[{"no":"1","chunks":[{"en":"If my sisters were here now,","ko":"만약 나의 자매들이 지금 여기에 있다면,","k":"V","lab":"V were (are 아님)"},{"en":"we would have a good time together.","ko":"우리는 함께 즐거운 시간을 보낼 것이다.","k":"C","lab":"C would + 동사원형 주절"}],"tr":"만약 나의 자매들이 지금 여기에 있다면, 우리는 함께 즐거운 시간을 보낼 것이다.","why":"&ldquo;지금 여기에 있다면&rdquo;은 지금 사실과 반대라서 가정법 과거예요. if절은 과거시제 <b>were</b>(be: ~이다, 있다)를 써서 <b>If my sisters were here</b>(5단어)가 돼요. 뒤의 주절은 would + 동사원형(would have: have는 &ldquo;보내다&rdquo;)으로 짝이 맞아요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","were (과거시제)"],["c","주절","would have"],["s","주어","my sisters"]],"verb":{"ok":"were","no":"are"},"note":{"t":"쓰기: If ~ were here, would have","lines":["If my sisters were here, we would have","지금 사실과 반대라서 if절 were, 주절 would + 동사원형"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"___ now, we would have a good time together.","kor":"만약 나의 자매들이 지금 여기에 있다면, 우리는 함께 즐거운 시간을 보낼 것이다. &lt;조건&gt; be, here, my sisters를 사용하시오. 5단어로 쓰시오.","pts":["5.1"]},{"no":"2","chunks":[{"en":"They only met last month,","ko":"그들은 겨우 지난달에 만났지만,","k":"","lab":""},{"en":"but they looked as if","ko":"하지만 마치 ~처럼 보였다","k":"C","lab":"C looked + as if (과거)"},{"en":"they had become friends years ago.","ko":"그들이 수년 전에 친구가 되었던 것처럼.","k":"V","lab":"V had become (became 아님)"}],"tr":"그들은 겨우 지난달에 만났지만, 마치 수년 전에 친구가 된 것처럼 보였다.","why":"주절의 동사 <b>looked</b>(look: 보이다의 과거형)보다 친구가 된 것이 &ldquo;수년 전&rdquo;으로 더 앞선 일이에요. 그래서 as if절에 <b>had become</b>(become: 되다)을 써서 <b>as if they had become friends</b>(6단어)가 돼요.","ex":"<b>as if</b>: 주절과 같은 때의 일이면 <b>과거시제</b>(be동사는 were), 주절보다 더 앞선 일이면 <b>had p.p.</b>","st":[["v","주절 동사","looked (과거)"],["m","시간 단서","years ago (더 앞선 시점)"],["v","as if절","had become"]],"verb":{"ok":"had become","no":"became"},"note":{"t":"쓰기: as if + had p.p.","lines":["looked as if they had become friends","years ago(수년 전)는 looked(보였다)보다 앞선 일이라 had p.p."]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"They only met last month, but they looked ___ years ago.","kor":"그들은 겨우 지난달에 만났지만, 마치 수년 전에 친구가 된 것처럼 보였다. &lt;조건&gt; become, friends를 사용하시오. 6단어로 쓰시오.","pts":["5.3"]},{"no":"3","chunks":[{"en":"If you had been more careful,","ko":"네가 좀 더 신중했더라면,","k":"C","lab":"C if절 had p.p."},{"en":"you could have avoided making such mistakes.","ko":"너는 그러한 실수를 하는 것을 피할 수 있었을 것이다.","k":"V","lab":"V could have avoided (could avoid 아님)"}],"tr":"네가 좀 더 신중했더라면, 너는 그러한 실수를 하는 것을 피할 수 있었을 것이다.","why":"if절의 동사가 <b>had been</b>(be: ~이다)이에요. had p.p.는 가정법 과거완료라서 주절은 could + <b>have p.p.</b>가 짝이에요. avoid(avoid: 피하다)를 써서 <b>you could have avoided</b>(4단어)가 돼요. 뒤의 making such mistakes는 &ldquo;그러한 실수를 하는 것&rdquo;이에요(avoid 뒤에는 v-ing).","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","had been (had p.p.)"],["c","주절","could + have p.p."],["v","동사","have avoided"]],"verb":{"ok":"could have avoided","no":"could avoid"},"note":{"t":"쓰기: had been + could have avoided","lines":["If you had been ~, you could have avoided","if절이 had p.p.라 주절은 could have p.p."]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"If you had been more careful, ___ making such mistakes.","kor":"네가 좀 더 신중했더라면, 너는 그러한 실수를 하는 것을 피할 수 있었을 것이다. &lt;조건&gt; avoid를 사용하시오. 4단어로 쓰시오.","pts":["5.1"]},{"no":"4","chunks":[{"en":"I could make you a cup of coffee","ko":"나는 네게 커피 한 잔을 만들어 줄 수 있을 것이다","k":"V","lab":"V could make (can make 아님)"},{"en":"if we had any left.","ko":"우리가 남은 것이 좀 있다면.","k":"C","lab":"C if절 had (과거시제)"}],"tr":"우리가 남은 것이 좀 있다면 네게 커피 한 잔을 만들어 줄 수 있을 것이다.","why":"&ldquo;남은 것이 없어서 못 만든다&rdquo;는 지금 사실이에요. 이것을 사실과 반대로 바꾸면 가정법 과거예요. 주절은 <b>can → could</b>, if절은 <b>don’t have → had</b>로 바꿔서 <b>I could make you a cup of coffee if we had any left</b>가 돼요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","주절","could make (can → could)"],["c","if절 동사","had (don’t have → had)"]],"verb":{"ok":"could make","no":"can make"},"note":{"t":"쓰기: 현재 사실의 반대는 과거형","lines":["can’t make를 could make, don’t have를 had로","지금 사실과 반대라서 can을 could로, don’t have를 had로 바꾼다"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"I ___.","kor":"I can’t make you a cup of coffee because we don’t have any left.<br>(우리가 남은 것이 없어서 너에게 커피 한 잔을 만들어 줄 수 없다.)<br>&rarr; 가정법 문장으로","pts":["5.1"]},{"no":"5","chunks":[{"en":"If Mr. Jenkins had arrived on time,","ko":"젠킨스 씨가 제시간에 도착했다면,","k":"C","lab":"C if절 had p.p."},{"en":"he would not have missed the meeting.","ko":"그는 회의를 놓치지 않았을 것이다.","k":"V","lab":"V would not have missed (missed 아님)"}],"tr":"Jenkins씨가 제시간에 도착했다면, 그는 회의를 놓치지 않았을 것이다.","why":"&ldquo;도착하지 않아서 놓쳤다&rdquo;는 과거 사실이에요. 사실과 반대로 바꾸면 가정법 과거완료예요. if절은 <b>had arrived</b>(arrive: 도착하다), 주절은 <b>would not have missed</b>(miss: 놓치다)로 써요. 원래 문장의 부정(did not arrive)은 긍정(had arrived)으로, 긍정(missed)은 부정(would not have missed)으로 뒤집혀요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","had arrived (did not arrive → had arrived)"],["c","주절","would not have missed (missed → would not have missed)"]],"verb":{"ok":"would not have missed","no":"missed"},"note":{"t":"쓰기: 지난 일의 반대는 had p.p.","lines":["did not arrive를 had arrived로, missed를 would not have missed로","지난 일과 반대라서 if절 had p.p., 주절 would have p.p."]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"If ___.","kor":"Mr. Jenkins did not arrive on time, so he missed the meeting.<br>(Jenkins씨는 제시간에 도착하지 않아서 회의를 놓쳤다.)<br>&rarr; 가정법 문장으로","pts":["5.1"]},{"no":"6","chunks":[{"en":"Tamara would stay up late often","ko":"타마라는 자주 늦게까지 깨어 있을 것이다","k":"V","lab":"V would stay up (stays up 아님)"},{"en":"if she didn’t get up early for work every day.","ko":"매일 출근을 위해 일찍 일어나지 않는다면.","k":"C","lab":"C if절 didn’t (과거시제)"}],"tr":"매일 출근을 위해 일찍 일어나지 않는다면 Tamara는 자주 늦게까지 깨어 있을 것이다.","why":"지금 사실(자주 늦게까지 깨어 있지 않고, 일찍 일어난다)을 반대로 바꾸는 가정법 과거예요. 주절은 <b>would stay up</b>(stay up: 깨어 있다), if절은 <b>didn’t get up</b>(get up: 일어나다)이에요. 긍정과 부정이 서로 뒤집혀요: doesn’t stay up → would stay up / gets up → didn’t get up.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","주절","would stay up (doesn’t stay up → would stay up)"],["c","if절 동사","didn’t get up (gets up → didn’t get up)"]],"verb":{"ok":"would stay up","no":"stays up"},"note":{"t":"쓰기: 현재 사실의 반대는 과거형","lines":["doesn’t stay up을 would stay up으로, gets up을 didn’t get up으로","지금 사실과 반대라서 if절은 과거형, 주절은 would + 동사원형"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"Tamara ___.","kor":"Tamara doesn’t stay up late often because she gets up early for work every day.<br>(Tamara는 매일 출근을 위해 일찍 일어나기 때문에 자주 늦게까지 깨어 있지 않는다.)<br>&rarr; 가정법 문장으로","pts":["5.1"]},{"no":"7-1","chunks":[{"en":"If humans","ko":"만약 인류가","k":"C","lab":"C if절 시작"},{"en":"owned faster spaceships than the current ones,","ko":"현재의 것들보다 더 빠른 우주선을 소유했다면,","k":"V","lab":"V owned (had owned 아님)"},{"en":"we could go very far into space.","ko":"우리는 우주로 매우 멀리 갈 수 있을 것이다.","k":"C","lab":"C could + 동사원형 주절"}],"tr":"만약 인류가 현재의 것들보다 더 빠른 우주선을 소유했다면, 우리는 우주로 매우 멀리 갈 수 있을 것이다.","why":"주절의 동사가 <b>could go</b>(could + 동사원형)라서 가정법 과거예요. 지금 우리가 가진 우주선과 반대로 상상하는 이야기라서 if절은 과거시제여야 해요. <b>had owned → owned</b>(own: 소유하다)로 고쳐요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","주절","could go (could + 동사원형)"],["c","if절 동사","had owned → owned"]],"verb":{"ok":"owned","no":"had owned"},"note":{"t":"틀린 곳 고치기: had owned를 owned로","lines":["If humans owned + could go","주절이 could + 동사원형이라 지금 사실과 반대, if절은 과거형 owned"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"<u>If humans ⓐ had owned faster spaceships than the current ones, we could go very far into space.</u> Also, we would ⓑ know about the existence of aliens for sure if we were able to explore faraway planets. If we ⓒ invested more in space exploration from now on, all of these dreams may come true in the near future.","pts":["5.1"]},{"no":"7-2","chunks":[{"en":"Also, we","ko":"또한, 우리는","k":"S","lab":"S 주어"},{"en":"would know about the existence of aliens for sure","ko":"외계인의 존재에 대해 확실히 알 수 있을 것이다","k":"V","lab":"V would know (would have known 아님)"},{"en":"if we were able to explore faraway planets.","ko":"우리가 멀리 떨어진 행성들을 탐험할 수 있다면.","k":"C","lab":"C if절 were (과거시제)"}],"tr":"또한, 우리가 멀리 떨어진 행성들을 탐험할 수 있다면 우리는 외계인의 존재에 대해 확실히 알 수 있을 것이다.","why":"if절의 동사가 과거시제 <b>were</b>(be: ~이다)예요. 가정법 과거라서 주절은 would + 동사원형인 <b>know</b>(know: 알다)가 맞아요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","were (과거시제)"],["c","주절","would + 동사원형"],["v","동사","know (맞음)"]],"verb":{"ok":"would know","no":"would have known"},"note":{"t":"if절 were와 짝은 would + 동사원형","lines":["if we were + would know","if절이 과거형 were라 주절은 would + 동사원형 know(이미 맞음)"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"If humans ⓐ had owned faster spaceships than the current ones, we could go very far into space. <u>Also, we would ⓑ know about the existence of aliens for sure if we were able to explore faraway planets.</u> If we ⓒ invested more in space exploration from now on, all of these dreams may come true in the near future.","pts":["5.1"]},{"no":"7-3","chunks":[{"en":"If we","ko":"만약 우리가","k":"C","lab":"C 조건 if절 단서"},{"en":"invest more in space exploration from now on,","ko":"지금부터 우주 탐사에 더 투자한다면,","k":"V","lab":"V invest (invested 아님)"},{"en":"all of these dreams may come true in the near future.","ko":"이 모든 꿈이 가까운 미래에 실현될지도 모른다.","k":"C","lab":"C may 주절"}],"tr":"만약 지금부터 우리가 우주 탐사에 더 투자한다면, 가까운 미래에 이 모든 꿈이 실현될지도 모른다.","why":"주절의 동사가 <b>may come</b>(come: 오다)이에요. 앞으로 더 투자하는 것(from now on: 지금부터)은 일어날 수 있는 일(조건 부사절)이라서 if절은 현재시제여야 해요. <b>invested → invest</b>(invest: 투자하다)로 고쳐요.","ex":"<b>일어날 수 있는 일</b>(조건 부사절)은 if절에 <b>현재시제</b>를 써요. 주절은 will 등이에요. 미래의 일이어도 if절에는 will을 쓰지 않아요.","st":[["c","주절","may come"],["m","시간 단서","from now on (앞으로)"],["c","if절 동사","invested → invest"]],"verb":{"ok":"invest","no":"invested"},"note":{"t":"틀린 곳 고치기: invested를 invest로","lines":["If we invest + may come","주절이 may라 일어날 수 있는 일, from now on(지금부터)이라 현재형"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"If humans ⓐ had owned faster spaceships than the current ones, we could go very far into space. Also, we would ⓑ know about the existence of aliens for sure if we were able to explore faraway planets. <u>If we ⓒ invested more in space exploration from now on, all of these dreams may come true in the near future.</u>","pts":["5.2"]},{"no":"8-1","chunks":[{"en":"Over the past century,","ko":"지난 세기 동안,","k":"C","lab":"C 기간 표현"},{"en":"the world has seen unbelievable developments.","ko":"세계는 믿을 수 없는 발전을 보아왔다.","k":"V","lab":"V has seen (이미 맞음)"}],"tr":"지난 세기 동안, 세계는 믿을 수 없는 발전을 보아왔다.","why":"","ex":"","st":[],"verb":{"ok":"has seen","no":"saw"},"note":{"t":"앞뒤 문장을 이어 주는 문장","lines":["Over the past century + has seen","가정법 문제가 아니라 지난 세기부터 지금까지를 말하는 문장이다"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"<u>Over the past century, the world has seen unbelievable developments.</u> Some inventions looked as if they ⓐ were from a science fiction movie to people back then. However, none of these developments would ⓑ be possible if the cost of electricity had not dropped. Therefore, if electricity ⓒ became cheaper, it will probably lead to greater improvements."},{"no":"8-2","chunks":[{"en":"Some inventions looked as if","ko":"어떤 발명품들은 마치 ~처럼 보였다","k":"C","lab":"C looked + as if (과거)"},{"en":"they were from a science fiction movie","ko":"공상과학 영화에서 나온","k":"V","lab":"V were (had been 아님)"},{"en":"to people back then.","ko":"그 당시 사람들에게.","k":"","lab":""}],"tr":"어떤 발명품들은 그 당시 사람들에게 마치 공상과학 영화에서 나온 것처럼 보였다.","why":"주절의 동사 <b>looked</b>(look: 보이다의 과거형)와 공상과학 영화에서 나온 것 같은 때가 같아요. 같은 시점이라서 as if절에 과거시제 <b>were</b>(be: ~이다)가 맞아요.","ex":"<b>as if</b>: 주절과 같은 때의 일이면 <b>과거시제</b>(be동사는 were), 주절보다 더 앞선 일이면 <b>had p.p.</b>","st":[["v","주절 동사","looked (과거)"],["v","as if절","were (같은 시점, 맞음)"]],"verb":{"ok":"were","no":"had been"},"note":{"t":"같은 시점이면 as if절 과거형","lines":["looked as if they were","보였던 때와 같은 시점이라 과거형 were(이미 맞음)"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"Over the past century, the world has seen unbelievable developments. <u>Some inventions looked as if they ⓐ were from a science fiction movie to people back then.</u> However, none of these developments would ⓑ be possible if the cost of electricity had not dropped. Therefore, if electricity ⓒ became cheaper, it will probably lead to greater improvements.","pts":["5.3"]},{"no":"8-3","chunks":[{"en":"However, none of these developments","ko":"그러나, 이러한 발전 중 어떤 것도","k":"S","lab":"S 주어"},{"en":"would have been possible","ko":"가능하지 않았을 것이다","k":"V","lab":"V have been (be 아님)"},{"en":"if the cost of electricity had not dropped.","ko":"전기 비용이 떨어지지 않았다면.","k":"C","lab":"C had p.p. (과거완료 if절)"}],"tr":"그러나, 전기 비용이 떨어지지 않았다면 이러한 발전 중 어떤 것도 가능하지 않았을 것이다.","why":"if절의 동사가 <b>had not dropped</b>(drop: 떨어지다)예요. had p.p.는 가정법 과거완료라서 주절은 would + <b>have p.p.</b>가 짝이에요. <b>be → have been</b>으로 고쳐요.","ex":"<b>짝 맞추기</b>: if + 과거시제 ↔ would + 동사원형 / if + had p.p. ↔ would + have p.p. (would 대신 could, might, should도 같아요)","st":[["c","if절 동사","had not dropped (had p.p.)"],["c","주절","would + have p.p."],["v","동사","be → have been"]],"verb":{"ok":"have been","no":"be"},"note":{"t":"if절 had p.p.와 짝은 would have p.p.","lines":["had not dropped + would have been","지난 일과 반대라서 be를 have been으로 고친다"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"Over the past century, the world has seen unbelievable developments. Some inventions looked as if they ⓐ were from a science fiction movie to people back then. <u>However, none of these developments would ⓑ be possible if the cost of electricity had not dropped.</u> Therefore, if electricity ⓒ became cheaper, it will probably lead to greater improvements.","pts":["5.1"]},{"no":"8-4","chunks":[{"en":"Therefore, if electricity","ko":"그러므로, 만약 전기가","k":"C","lab":"C 조건 if절 단서"},{"en":"becomes cheaper,","ko":"더 싸진다면,","k":"V","lab":"V becomes (became 아님)"},{"en":"it will probably lead to greater improvements.","ko":"그것은 아마도 더 큰 발전으로 이어질 것이다.","k":"C","lab":"C will 주절"}],"tr":"그러므로, 만약 전기가 더 싸진다면, 그것은 아마도 더 큰 발전으로 이어질 것이다.","why":"주절의 동사가 <b>will lead</b>(lead: 이어지다)예요. 앞으로 전기가 더 싸질 수 있다는 것은 일어날 수 있는 일(조건 부사절)이라서 if절은 현재시제여야 해요. <b>became → becomes</b>(become: 되다, 주어가 단수라서 -s)로 고쳐요.","ex":"<b>일어날 수 있는 일</b>(조건 부사절)은 if절에 <b>현재시제</b>를 써요. 주절은 will 등이에요. 미래의 일이어도 if절에는 will을 쓰지 않아요.","st":[["c","주절","will lead"],["c","가능성","일어날 수 있는 일"],["c","if절 동사","became → becomes"]],"verb":{"ok":"becomes","no":"became"},"note":{"t":"틀린 곳 고치기: became을 becomes로","lines":["if electricity becomes + will lead","주절이 will이라 일어날 수 있는 일, if절은 현재형 becomes"]},"taps":[{"k":"C","t":"if절·as if절의 단서를 누르세요"}],"ctx":"Over the past century, the world has seen unbelievable developments. Some inventions looked as if they ⓐ were from a science fiction movie to people back then. However, none of these developments would ⓑ be possible if the cost of electricity had not dropped. <u>Therefore, if electricity ⓒ became cheaper, it will probably lead to greater improvements.</u>","pts":["5.2"]}],"cprompt":"알맞은 동사를 고르세요"}];